// §209 Live provider quality sampling + human-labelled answer sets.
// portal_ai_quality: trace/usage sample (0 LLM) + owner gold sets
// with optional live provider run. Run from website repo root
// (folder that contains OmniFlow-Control-Plane/).
// Expected clean: applied N already 0 warnings 0. Rerun: 0/N/0.
import fs from "fs";
import { createRequire } from "module";
const require = createRequire(import.meta.url);
const BACKUP_TAG = ".pre_ai_quality_209.bak";
let applied = 0, already = 0, warnings = 0;
if (!fs.existsSync("OmniFlow-Control-Plane") || !fs.statSync("OmniFlow-Control-Plane").isDirectory()) {
  console.log("X Run this from the website repo root (bot root) - the folder that contains OmniFlow-Control-Plane/. Nothing was written.");
  process.exit(1);
}
function compilePython(pathArg) {
  const { spawnSync } = require("child_process");
  for (const py of ["python3", "python", "py"]) {
    const probe = spawnSync(py, ["--version"], { encoding: "utf8" });
    if (probe.status !== 0) continue;
    const check = spawnSync(py, ["-c", "import sys;sys.exit(0 if sys.version_info[0]>=3 else 1)"], { encoding: "utf8" });
    if (check.status !== 0) continue;
    const result = spawnSync(py, ["-c", "import py_compile,sys;py_compile.compile(sys.argv[1],doraise=True);sys.exit(0)", pathArg], { encoding: "utf8" });
    return result.status === 0;
  }
  console.log("  (python not found - skipped compile guard)");
  return true;
}
function writeNewRepair(repoPath, marker, isCp, content) {
  try {
  let existed = false;
  if (fs.existsSync(repoPath)) {
    if (fs.statSync(repoPath).isDirectory()) {
      let target = repoPath + ".dir_conflict.bak";
      let n = 1;
      while (fs.existsSync(target)) { target = repoPath + ".dir_conflict.bak." + n; n++; }
      fs.renameSync(repoPath, target);
      console.log("! " + repoPath + " was a DIRECTORY on this machine - renamed to " + target + "; writing the real file.");
      warnings++;
    } else existed = true;
  }
  if (!existed) {
    const cut = Math.max(repoPath.lastIndexOf("/"), repoPath.lastIndexOf("\\"));
    if (cut > 0) fs.mkdirSync(repoPath.slice(0, cut), { recursive: true });
    fs.writeFileSync(repoPath, content, "utf8");
    if (isCp && repoPath.endsWith(".py") && !compilePython(repoPath)) {
      fs.unlinkSync(repoPath);
      console.log("X " + repoPath + " FAILED to compile - not written");
      warnings++;
      return;
    }
    console.log("+ " + repoPath + " (new file)");
    applied++;
    return;
  }
  const original = fs.readFileSync(repoPath, "utf8").replace(/\r\n/g, "\n");
  if (original.includes(marker)) {
    console.log("= " + repoPath + " (already correct)");
    already++;
    return;
  }
  const backup = repoPath + BACKUP_TAG;
  if (!fs.existsSync(backup)) fs.copyFileSync(repoPath, backup);
  fs.writeFileSync(repoPath, content, "utf8");
  if (isCp && repoPath.endsWith(".py") && !compilePython(repoPath)) {
    fs.copyFileSync(backup, repoPath);
    console.log("X " + repoPath + " FAILED to compile - old copy restored");
    warnings++;
    return;
  }
  console.log("+ " + repoPath + " (REPAIRED - old copy kept as " + BACKUP_TAG + ")");
  applied++;
  } catch (err) {
    console.log("X " + repoPath + " FAILED: " + err.message);
    warnings++;
  }
}
writeNewRepair("omniflow-backend-patch/portal_ai_quality.py", "def sample_quality", false,
    "\"\"\"Live AI quality sampling + human-labelled answer sets (\u00a7209).\n\nTwo complementary signals, both fail-soft and opt-in:\n\n1. **Live quality sample** - deterministic mining of recent\n   ``portal_brain_traces`` (and optional ``portal_ai_usage``) for one\n   workspace or the whole platform. Zero LLM cost. Surfaces decision mix,\n   confidence, grounding/citation share, handoff reasons, guard blocks,\n   and engine failure rate. This is the \"is the live provider behaving?\"\n   dashboard number without inventing scores.\n\n2. **Human-labelled answer sets** - owner-authored gold rows\n   (customer message + expected decision + optional expected keywords /\n   forbidden phrases). ``run_labels`` checks each row against the brain's\n   pure decision/policy gates (zero LLM by default). Optional\n   ``include_live=true`` runs one real ``portal_llm.chat_json`` call per\n   row under ``usage_scope(\"ai_quality_label\", ...)`` so cost is visible\n   and gated by the existing AI daily-cap / kill switch. Labels never\n   auto-send customer messages.\n\nLaws: no second chatbot, no background worker, no fake pass rates, no\ncustomer PII required to create a set. Tenant-scoped owner API; platform\nadmin can sample across workspaces. Defaults empty / OFF.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport logging\nimport os\nimport re\nfrom datetime import datetime, timezone\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\n\nlogger = logging.getLogger(\"omniflow.portal-ai-quality\")\n\nbp = Blueprint(\"portal_ai_quality\", __name__, url_prefix=\"/api/v1/portal\")\n\nLABELS_TABLE = \"portal_ai_label_sets\"\n_DDL_READY = False\n\nDEFAULT_DAYS = int(os.environ.get(\"OF_AI_QUALITY_DAYS\", \"7\") or 7)\nSAMPLE_MAX = int(os.environ.get(\"OF_AI_QUALITY_SAMPLE_MAX\", \"500\") or 500)\nMAX_SETS = int(os.environ.get(\"OF_AI_LABEL_SETS_MAX\", \"20\") or 20)\nMAX_ITEMS = int(os.environ.get(\"OF_AI_LABEL_ITEMS_MAX\", \"40\") or 40)\nMAX_NAME = 80\nMAX_MESSAGE = int(os.environ.get(\"OF_AI_LABEL_MSG_MAX\", \"500\") or 500)\nMAX_NOTE = 200\nALLOWED_DECISIONS = (\"send\", \"handoff\", \"draft\")\nLIVE_MAX_TOKENS = int(os.environ.get(\"OF_AI_QUALITY_LIVE_MAX_TOKENS\", \"80\") or 80)\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_ai_label_sets (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  name TEXT NOT NULL DEFAULT '',\n  notes TEXT NOT NULL DEFAULT '',\n  items JSONB NOT NULL DEFAULT '[]'::jsonb,\n  is_active BOOLEAN NOT NULL DEFAULT TRUE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_ai_label_sets\n  ON portal_ai_label_sets (client_id, is_active, id DESC);\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    _DDL_READY = True\n\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\ndef _days(value: Any) -> int:\n    try:\n        days = int(value)\n    except Exception:\n        days = DEFAULT_DAYS\n    if days not in (1, 7, 14, 30):\n        days = DEFAULT_DAYS\n    return days\n\n\ndef _clamp_sample(value: Any) -> int:\n    try:\n        n = int(value)\n    except Exception:\n        n = SAMPLE_MAX\n    return max(20, min(SAMPLE_MAX, n))\n\n\n# ---------------------------------------------------------------------------\n# Live quality sample (traces)\n# ---------------------------------------------------------------------------\n\n\ndef _parse_grounding(raw: Any) -> Dict[str, Any]:\n    if isinstance(raw, str):\n        try:\n            raw = json.loads(raw or \"{}\")\n        except Exception:\n            raw = {}\n    return raw if isinstance(raw, dict) else {}\n\n\ndef sample_quality(cur, client_id: Optional[int], days: int = DEFAULT_DAYS,\n                   limit: int = SAMPLE_MAX) -> Dict[str, Any]:\n    \"\"\"Deterministic quality snapshot over brain traces (+ usage if present).\n\n    ``client_id=None`` = platform-wide (admin). Never raises past the caller;\n    missing tables blank only the affected block.\n    \"\"\"\n    days = _days(days)\n    limit = _clamp_sample(limit)\n    out: Dict[str, Any] = {\n        \"days\": days,\n        \"generated_at\": datetime.now(timezone.utc).isoformat(),\n        \"scope\": \"workspace\" if client_id else \"platform\",\n        \"client_id\": client_id,\n        \"traces\": {\n            \"total\": 0, \"by_decision\": {}, \"by_kind\": {},\n            \"avg_confidence\": None, \"grounded_share\": None,\n            \"cited_share\": None, \"auto_reply_blocked_share\": None,\n            \"guard_blocked\": 0, \"handoff_reasons\": {},\n            \"sample\": [],\n        },\n        \"usage\": None,\n        \"signals\": [],\n    }\n\n    # --- traces ---\n    try:\n        sql = (\n            \"SELECT id, client_id, conversation_id, kind, decision, grounding,\"\n            \" created_at FROM \" + portal_db._q(\"portal_brain_traces\") +\n            \" WHERE created_at >= NOW() - (%s || ' days')::interval\"\n        )\n        params: List[Any] = [str(days)]\n        if client_id is not None:\n            sql += \" AND client_id = %s\"\n            params.append(int(client_id))\n        sql += \" ORDER BY id DESC LIMIT %s\"\n        params.append(limit)\n        cur.execute(sql, tuple(params))\n        rows = portal_db.rows(cur)\n    except Exception as error:\n        logger.warning(\"ai quality traces failed: %s\", error)\n        rows = []\n        out[\"signals\"].append({\n            \"key\": \"traces_unavailable\",\n            \"severity\": \"info\",\n            \"title\": \"Brain traces not readable yet\",\n            \"detail\": \"Quality sampling needs portal_brain_traces. \"\n                      \"It appears after the assistant answers a few chats.\",\n        })\n\n    confidences: List[float] = []\n    grounded = 0\n    cited = 0\n    auto_blocked = 0\n    guard_blocked = 0\n    by_decision: Dict[str, int] = {}\n    by_kind: Dict[str, int] = {}\n    reasons: Dict[str, int] = {}\n    sample_rows: List[Dict[str, Any]] = []\n\n    for row in rows:\n        decision = str(row.get(\"decision\") or \"handoff\")\n        kind = str(row.get(\"kind\") or \"draft\")\n        by_decision[decision] = by_decision.get(decision, 0) + 1\n        by_kind[kind] = by_kind.get(kind, 0) + 1\n        g = _parse_grounding(row.get(\"grounding\"))\n        conf = g.get(\"confidence\")\n        try:\n            if conf is not None:\n                confidences.append(float(conf))\n        except Exception:\n            pass\n        if g.get(\"grounded\") is True or g.get(\"kb_hit\") is True:\n            grounded += 1\n        if g.get(\"cited\") is True or (g.get(\"citations\") or g.get(\"sources\")):\n            cited += 1\n        if g.get(\"agent_auto_reply\") is False:\n            auto_blocked += 1\n        if g.get(\"guard_blocked\") or g.get(\"guard_level\") in (\"high\", \"block\"):\n            guard_blocked += 1\n        reason = str(g.get(\"reason\") or g.get(\"handoff_reason\") or \"\").strip()\n        if decision == \"handoff\" and reason:\n            reasons[reason] = reasons.get(reason, 0) + 1\n        if len(sample_rows) < 12:\n            sample_rows.append({\n                \"id\": int(row.get(\"id\") or 0),\n                \"client_id\": int(row.get(\"client_id\") or 0),\n                \"conversation_id\": row.get(\"conversation_id\"),\n                \"kind\": kind,\n                \"decision\": decision,\n                \"confidence\": confidences[-1] if confidences and conf is not None else None,\n                \"created_at\": str(row.get(\"created_at\") or \"\"),\n            })\n\n    total = len(rows)\n    tr = out[\"traces\"]\n    tr[\"total\"] = total\n    tr[\"by_decision\"] = by_decision\n    tr[\"by_kind\"] = by_kind\n    tr[\"avg_confidence\"] = (\n        round(sum(confidences) / len(confidences), 3) if confidences else None\n    )\n    if total:\n        tr[\"grounded_share\"] = round(grounded / total, 3)\n        tr[\"cited_share\"] = round(cited / total, 3)\n        tr[\"auto_reply_blocked_share\"] = round(auto_blocked / total, 3)\n    tr[\"guard_blocked\"] = guard_blocked\n    tr[\"handoff_reasons\"] = dict(\n        sorted(reasons.items(), key=lambda kv: (-kv[1], kv[0]))[:8]\n    )\n    tr[\"sample\"] = sample_rows\n\n    # --- usage (optional) ---\n    try:\n        sql_u = (\n            \"SELECT COUNT(*) AS calls,\"\n            \" COALESCE(SUM(CASE WHEN ok IS FALSE THEN 1 ELSE 0 END), 0) AS failed,\"\n            \" COALESCE(AVG(latency_ms), 0) AS avg_latency_ms\"\n            \" FROM \" + portal_db._q(\"portal_ai_usage\") +\n            \" WHERE created_at >= NOW() - (%s || ' days')::interval\"\n        )\n        params_u: List[Any] = [str(days)]\n        if client_id is not None:\n            sql_u += \" AND client_id = %s\"\n            params_u.append(int(client_id))\n        cur.execute(sql_u, tuple(params_u))\n        urows = portal_db.rows(cur)\n        u = urows[0] if urows else {}\n        calls = int(u.get(\"calls\") or 0)\n        failed = int(u.get(\"failed\") or 0)\n        out[\"usage\"] = {\n            \"calls\": calls,\n            \"failed\": failed,\n            \"fail_share\": round(failed / calls, 3) if calls else None,\n            \"avg_latency_ms\": int(float(u.get(\"avg_latency_ms\") or 0)),\n        }\n    except Exception as error:\n        logger.warning(\"ai quality usage failed: %s\", error)\n        out[\"usage\"] = None\n\n    # --- signals (deterministic thresholds, thin-data quiet) ---\n    signals = out[\"signals\"]\n    if total == 0 and not any(s.get(\"key\") == \"traces_unavailable\" for s in signals):\n        signals.append({\n            \"key\": \"thin_data\",\n            \"severity\": \"info\",\n            \"title\": \"Not enough AI activity yet\",\n            \"detail\": \"Quality sampling needs recent brain answers. \"\n                      \"Try again after the assistant handles a few chats.\",\n        })\n    if total >= 10:\n        handoff = by_decision.get(\"handoff\", 0)\n        handoff_share = handoff / total\n        if handoff_share >= 0.45:\n            signals.append({\n                \"key\": \"handoff_high\",\n                \"severity\": \"warn\" if handoff_share < 0.7 else \"critical\",\n                \"title\": \"Handoff rate is elevated\",\n                \"detail\": (\n                    str(round(handoff_share * 100)) + \"% of recent brain \"\n                    \"decisions handed off to a human (\" + str(handoff) +\n                    \" of \" + str(total) + \").\"\n                ),\n            })\n        if confidences and (sum(confidences) / len(confidences)) < 0.55:\n            signals.append({\n                \"key\": \"confidence_low\",\n                \"severity\": \"warn\",\n                \"title\": \"Average confidence is low\",\n                \"detail\": \"Mean confidence \"\n                          + str(out[\"traces\"][\"avg_confidence\"])\n                          + \" over \" + str(len(confidences)) + \" scored answers.\",\n            })\n        if guard_blocked >= 3:\n            signals.append({\n                \"key\": \"guard_blocks\",\n                \"severity\": \"info\",\n                \"title\": \"Prompt-injection guard blocked replies\",\n                \"detail\": str(guard_blocked) + \" recent traces marked guard-blocked.\",\n            })\n    usage = out.get(\"usage\") or {}\n    if usage.get(\"calls\", 0) >= 10 and (usage.get(\"fail_share\") or 0) >= 0.15:\n        signals.append({\n            \"key\": \"provider_fail_high\",\n            \"severity\": \"critical\" if usage[\"fail_share\"] >= 0.3 else \"warn\",\n            \"title\": \"Live provider failures are elevated\",\n            \"detail\": (\n                str(round((usage[\"fail_share\"] or 0) * 100)) + \"% of LLM calls \"\n                \"failed in the window (\" + str(usage.get(\"failed\")) + \" of \"\n                + str(usage.get(\"calls\")) + \").\"\n            ),\n        })\n    out[\"signals\"] = signals\n    return out\n\n\n# ---------------------------------------------------------------------------\n# Label sets\n# ---------------------------------------------------------------------------\n\n\ndef _clean_item(raw: Any) -> Optional[Dict[str, Any]]:\n    if not isinstance(raw, dict):\n        return None\n    message = str(raw.get(\"message\") or raw.get(\"customer_message\") or \"\").strip()\n    if not message or len(message) > MAX_MESSAGE:\n        return None\n    decision = str(raw.get(\"expected_decision\") or raw.get(\"decision\") or \"send\").strip().lower()\n    if decision not in ALLOWED_DECISIONS:\n        decision = \"send\"\n    keywords: List[str] = []\n    for key in (\"expected_keywords\", \"keywords\"):\n        val = raw.get(key)\n        if isinstance(val, list):\n            for item in val:\n                text = str(item or \"\").strip().lower()\n                if text and text not in keywords:\n                    keywords.append(text[:40])\n        elif isinstance(val, str) and val.strip():\n            for part in re.split(r\"[,;|]\", val):\n                text = part.strip().lower()\n                if text and text not in keywords:\n                    keywords.append(text[:40])\n    forbidden: List[str] = []\n    for key in (\"forbidden_phrases\", \"forbidden\"):\n        val = raw.get(key)\n        if isinstance(val, list):\n            for item in val:\n                text = str(item or \"\").strip().lower()\n                if text and text not in forbidden:\n                    forbidden.append(text[:60])\n        elif isinstance(val, str) and val.strip():\n            for part in re.split(r\"[,;|]\", val):\n                text = part.strip().lower()\n                if text and text not in forbidden:\n                    forbidden.append(text[:60])\n    note = str(raw.get(\"note\") or \"\").strip()[:MAX_NOTE]\n    return {\n        \"message\": message[:MAX_MESSAGE],\n        \"expected_decision\": decision,\n        \"expected_keywords\": keywords[:12],\n        \"forbidden_phrases\": forbidden[:12],\n        \"note\": note,\n    }\n\n\ndef _normalize_items(raw: Any) -> List[Dict[str, Any]]:\n    if isinstance(raw, str):\n        try:\n            raw = json.loads(raw)\n        except Exception:\n            raw = []\n    if not isinstance(raw, list):\n        return []\n    out: List[Dict[str, Any]] = []\n    for item in raw[:MAX_ITEMS]:\n        clean = _clean_item(item)\n        if clean:\n            out.append(clean)\n    return out\n\n\ndef _shape_set(row: Dict[str, Any]) -> Dict[str, Any]:\n    items = _normalize_items(row.get(\"items\"))\n    return {\n        \"id\": int(row.get(\"id\") or 0),\n        \"name\": str(row.get(\"name\") or \"\"),\n        \"notes\": str(row.get(\"notes\") or \"\"),\n        \"items\": items,\n        \"item_count\": len(items),\n        \"is_active\": bool(row.get(\"is_active\", True)),\n        \"updated_at\": str(row.get(\"updated_at\") or \"\"),\n        \"created_at\": str(row.get(\"created_at\") or \"\"),\n    }\n\n\ndef _validate_set_payload(payload: Dict[str, Any]) -> Tuple[Optional[str], Dict[str, Any]]:\n    name = str(payload.get(\"name\") or \"\").strip()\n    if not name or len(name) > MAX_NAME:\n        return (\"name is required (max \" + str(MAX_NAME) + \" characters).\", {})\n    notes = str(payload.get(\"notes\") or \"\").strip()[:MAX_NOTE]\n    items = _normalize_items(payload.get(\"items\"))\n    if not items:\n        return (\"Add at least one labelled example (customer message + expected decision).\", {})\n    if len(items) > MAX_ITEMS:\n        return (\"A set can hold at most \" + str(MAX_ITEMS) + \" examples.\", {})\n    is_active = payload.get(\"is_active\", True)\n    if not isinstance(is_active, bool):\n        is_active = bool(is_active)\n    return None, {\n        \"name\": name[:MAX_NAME],\n        \"notes\": notes,\n        \"items\": items,\n        \"is_active\": is_active,\n    }\n\n\ndef list_sets(cur, client_id: int) -> List[Dict[str, Any]]:\n    _ensure_ddl(cur)\n    cur.execute(\n        \"SELECT id, name, notes, items, is_active, created_at, updated_at FROM \"\n        + portal_db._q(LABELS_TABLE) +\n        \" WHERE client_id = %s ORDER BY is_active DESC, id DESC LIMIT %s\",\n        (client_id, max(1, min(50, MAX_SETS * 2))),\n    )\n    return [_shape_set(row) for row in portal_db.rows(cur)]\n\n\ndef get_set(cur, client_id: int, set_id: int) -> Optional[Dict[str, Any]]:\n    _ensure_ddl(cur)\n    cur.execute(\n        \"SELECT id, name, notes, items, is_active, created_at, updated_at FROM \"\n        + portal_db._q(LABELS_TABLE) +\n        \" WHERE client_id = %s AND id = %s\",\n        (client_id, set_id),\n    )\n    rows = portal_db.rows(cur)\n    return _shape_set(rows[0]) if rows else None\n\n\ndef _decision_from_policy(message: str, expected: str) -> Tuple[str, str]:\n    \"\"\"Zero-LLM check: policy gate + trivial keyword heuristics.\n\n    Returns (actual_decision, detail). Uses portal_brain._decide when a\n    synthetic reply is built from expected keywords; otherwise defaults to\n    send for benign text and handoff when the injection guard would block.\n    \"\"\"\n    detail = \"policy\"\n    try:\n        import portal_guard\n        inspected = portal_guard.inspect(message)\n        if portal_guard.blocks(inspected, \"standard\"):\n            return \"handoff\", \"guard_blocked\"\n    except Exception:\n        pass\n\n    # Build a synthetic \"model reply\" for the policy/decide path when we\n    # only have the customer message: prefer expected keywords as a stand-in\n    # answer so forbidden-promise detection still runs on owner-supplied text.\n    synthetic_reply = message[:180]\n    try:\n        import portal_brain\n        decision, reason = portal_brain._decide(\n            {\"reply\": synthetic_reply, \"confidence\": 0.9}, {}\n        )\n        if decision == \"handoff\":\n            return \"handoff\", str(reason or \"policy_handoff\")\n    except Exception as error:\n        detail = \"decide_error:\" + type(error).__name__\n\n    # If owner expects handoff and message is short/empty of commerce signal,\n    # still allow expected-match via keyword absence - actual stays send.\n    return \"send\", detail\n\n\ndef _keywords_ok(text: str, keywords: List[str]) -> bool:\n    if not keywords:\n        return True\n    low = text.lower()\n    return all(k in low for k in keywords)\n\n\ndef _forbidden_hit(text: str, phrases: List[str]) -> Optional[str]:\n    low = text.lower()\n    for phrase in phrases:\n        if phrase and phrase in low:\n            return phrase\n    return None\n\n\ndef evaluate_item(item: Dict[str, Any], include_live: bool = False,\n                  client_id: int = 0, cur=None) -> Dict[str, Any]:\n    \"\"\"Score one labelled example. Never raises.\"\"\"\n    message = str(item.get(\"message\") or \"\")\n    expected = str(item.get(\"expected_decision\") or \"send\")\n    keywords = list(item.get(\"expected_keywords\") or [])\n    forbidden = list(item.get(\"forbidden_phrases\") or [])\n    result: Dict[str, Any] = {\n        \"message\": message[:120],\n        \"expected_decision\": expected,\n        \"actual_decision\": None,\n        \"passed\": False,\n        \"mode\": \"deterministic\",\n        \"detail\": \"\",\n        \"live_reply\": None,\n        \"live_error\": None,\n    }\n    try:\n        actual, detail = _decision_from_policy(message, expected)\n        result[\"actual_decision\"] = actual\n        result[\"detail\"] = detail\n        decision_ok = actual == expected\n        # Keyword/forbidden checks apply to live reply when present, else\n        # to the customer message only for forbidden (owner sanity).\n        text_for_kw = message\n        live_reply = None\n        if include_live:\n            result[\"mode\"] = \"live_provider\"\n            try:\n                import portal_llm\n                system = (\n                    \"You are a concise commerce assistant. Reply in the \"\n                    \"customer's language. Return JSON \"\n                    \"{\\\"reply\\\": string, \\\"decision\\\": \\\"send\\\"|\\\"handoff\\\", \"\n                    \"\\\"confidence\\\": number}.\"\n                )\n                user = \"Customer message:\\\\n\" + message[:MAX_MESSAGE]\n                scope_cm = None\n                try:\n                    scope_cm = portal_llm.usage_scope(\n                        \"ai_quality_label\", int(client_id or 0), cur\n                    )\n                    scope_cm.__enter__()\n                except Exception:\n                    scope_cm = None\n                try:\n                    live = portal_llm.chat_json(system, user, max_tokens=LIVE_MAX_TOKENS)\n                finally:\n                    if scope_cm is not None:\n                        try:\n                            scope_cm.__exit__(None, None, None)\n                        except Exception:\n                            pass\n                if not isinstance(live, dict):\n                    result[\"live_error\"] = \"provider_unavailable_or_empty\"\n                    result[\"passed\"] = False\n                    result[\"detail\"] = \"live_call_failed\"\n                    return result\n                live_reply = str(live.get(\"reply\") or live.get(\"message\") or \"\")[:300]\n                live_decision = str(live.get(\"decision\") or \"\").strip().lower()\n                if live_decision not in ALLOWED_DECISIONS:\n                    # Fall back to policy on the live reply text.\n                    try:\n                        import portal_brain\n                        live_decision, _r = portal_brain._decide(\n                            {\"reply\": live_reply or message, \"confidence\": float(live.get(\"confidence\") or 0.5)},\n                            {},\n                        )\n                    except Exception:\n                        live_decision = \"send\"\n                result[\"actual_decision\"] = live_decision\n                result[\"live_reply\"] = live_reply\n                text_for_kw = live_reply or message\n                decision_ok = live_decision == expected\n                detail = \"live\"\n            except Exception as error:\n                result[\"live_error\"] = type(error).__name__ + \": \" + str(error)[:120]\n                result[\"passed\"] = False\n                result[\"detail\"] = \"live_exception\"\n                return result\n\n        kw_ok = _keywords_ok(text_for_kw, keywords) if (include_live and live_reply) else True\n        # When not live, keyword check is informational only on message if\n        # owner listed keywords that should appear in a good answer - skip hard fail.\n        if include_live and live_reply and keywords and not kw_ok:\n            result[\"passed\"] = False\n            result[\"detail\"] = \"missing_keywords\"\n            return result\n        hit = _forbidden_hit(text_for_kw, forbidden)\n        if hit:\n            result[\"passed\"] = False\n            result[\"detail\"] = \"forbidden:\" + hit\n            return result\n        # Non-live: decision match is the contract (guard/policy).\n        result[\"passed\"] = bool(decision_ok)\n        if not decision_ok:\n            result[\"detail\"] = \"decision_mismatch:\" + str(result[\"actual_decision\"])\n        else:\n            result[\"detail\"] = detail or \"ok\"\n        return result\n    except Exception as error:\n        result[\"detail\"] = type(error).__name__ + \": \" + str(error)[:120]\n        result[\"passed\"] = False\n        return result\n\n\ndef run_labels(cur, client_id: int, set_id: int,\n               include_live: bool = False) -> Dict[str, Any]:\n    label_set = get_set(cur, client_id, set_id)\n    if label_set is None:\n        return {\"error\": \"not_found\"}\n    if not label_set.get(\"is_active\", True):\n        return {\"error\": \"inactive\", \"set\": label_set}\n    items = label_set.get(\"items\") or []\n    results = [evaluate_item(item, include_live=include_live,\n                             client_id=client_id, cur=cur) for item in items]\n    passed = sum(1 for r in results if r.get(\"passed\"))\n    total = len(results)\n    score = round((passed / total) * 100, 1) if total else 0.0\n    return {\n        \"set_id\": set_id,\n        \"name\": label_set.get(\"name\"),\n        \"mode\": \"live_provider\" if include_live else \"deterministic\",\n        \"llm_calls\": total if include_live else 0,\n        \"passed\": passed,\n        \"total\": total,\n        \"score\": score,\n        \"status\": \"pass\" if total and passed == total else (\"empty\" if not total else \"fail\"),\n        \"results\": results,\n        \"generated_at\": datetime.now(timezone.utc).isoformat(),\n    }\n\n\n# ---------------------------------------------------------------------------\n# Owner HTTP API\n# ---------------------------------------------------------------------------\n\n\n@bp.get(\"/ai/quality\")\ndef get_quality():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    days = _days(request.args.get(\"days\"))\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            data = sample_quality(cur, client_id, days=days)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify(data), 200\n\n\n@bp.get(\"/ai/labels\")\ndef get_labels():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            sets = list_sets(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\n        \"sets\": sets,\n        \"limits\": {\"max_sets\": MAX_SETS, \"max_items\": MAX_ITEMS,\n                   \"max_message\": MAX_MESSAGE},\n        \"decisions\": list(ALLOWED_DECISIONS),\n    }), 200\n\n\n@bp.post(\"/ai/labels\")\ndef create_label_set():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    problem, clean = _validate_set_payload(payload)\n    if problem:\n        return jsonify({\"error\": {\"code\": \"bad_request\", \"message\": problem}}), 400\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"SELECT COUNT(*) AS total FROM \" + portal_db._q(LABELS_TABLE) +\n                \" WHERE client_id = %s\",\n                (client_id,),\n            )\n            rows = portal_db.rows(cur)\n            if int((rows[0] if rows else {}).get(\"total\") or 0) >= MAX_SETS:\n                return jsonify({\"error\": {\n                    \"code\": \"bad_request\",\n                    \"message\": \"Max \" + str(MAX_SETS) + \" label sets.\"}}), 400\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(LABELS_TABLE) +\n                \" (client_id, name, notes, items, is_active)\"\n                \" VALUES (%s, %s, %s, CAST(%s AS JSONB), %s) RETURNING id\",\n                (client_id, clean[\"name\"], clean[\"notes\"],\n                 json.dumps(clean[\"items\"], ensure_ascii=False),\n                 clean[\"is_active\"]),\n            )\n            rows = portal_db.rows(cur)\n            set_id = int((rows[0] if rows else {}).get(\"id\") or 0)\n            portal_db.log_action(\n                cur, client_id, \"ai.labels_saved\", \"customer_user\",\n                principal.get(\"user_id\"), None,\n                (\"Label set created: \" + clean[\"name\"])[:200],\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"set\": {\n        \"id\": set_id, \"name\": clean[\"name\"], \"notes\": clean[\"notes\"],\n        \"items\": clean[\"items\"], \"item_count\": len(clean[\"items\"]),\n        \"is_active\": clean[\"is_active\"],\n    }}), 200\n\n\n@bp.put(\"/ai/labels/<int:set_id>\")\ndef update_label_set(set_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    problem, clean = _validate_set_payload(payload)\n    if problem:\n        return jsonify({\"error\": {\"code\": \"bad_request\", \"message\": problem}}), 400\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"UPDATE \" + portal_db._q(LABELS_TABLE) +\n                \" SET name = %s, notes = %s, items = CAST(%s AS JSONB),\"\n                \" is_active = %s, updated_at = NOW()\"\n                \" WHERE id = %s AND client_id = %s RETURNING id\",\n                (clean[\"name\"], clean[\"notes\"],\n                 json.dumps(clean[\"items\"], ensure_ascii=False),\n                 clean[\"is_active\"], set_id, client_id),\n            )\n            rows = portal_db.rows(cur)\n            if not rows:\n                return jsonify({\"error\": {\n                    \"code\": \"not_found\",\n                    \"message\": \"No such label set in this workspace.\"}}), 404\n            portal_db.log_action(\n                cur, client_id, \"ai.labels_saved\", \"customer_user\",\n                principal.get(\"user_id\"), None,\n                (\"Label set updated: \" + clean[\"name\"])[:200],\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.delete(\"/ai/labels/<int:set_id>\")\ndef delete_label_set(set_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"UPDATE \" + portal_db._q(LABELS_TABLE) +\n                \" SET is_active = FALSE, updated_at = NOW()\"\n                \" WHERE id = %s AND client_id = %s RETURNING id\",\n                (set_id, client_id),\n            )\n            rows = portal_db.rows(cur)\n            if not rows:\n                return jsonify({\"error\": {\n                    \"code\": \"not_found\",\n                    \"message\": \"No such label set in this workspace.\"}}), 404\n            portal_db.log_action(\n                cur, client_id, \"ai.labels_archived\", \"customer_user\",\n                principal.get(\"user_id\"), None,\n                (\"Label set archived: \" + str(set_id))[:200],\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.post(\"/ai/labels/<int:set_id>/run\")\ndef run_label_set(set_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    include_live = payload.get(\"include_live\") is True\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            result = run_labels(cur, client_id, set_id, include_live=include_live)\n            if result.get(\"error\") == \"not_found\":\n                return jsonify({\"error\": {\n                    \"code\": \"not_found\",\n                    \"message\": \"No such label set in this workspace.\"}}), 404\n            if result.get(\"error\") == \"inactive\":\n                return jsonify({\"error\": {\n                    \"code\": \"bad_request\",\n                    \"message\": \"This label set is archived.\"}}), 400\n            portal_db.log_action(\n                cur, client_id, \"ai.labels_run\", \"customer_user\",\n                principal.get(\"user_id\"), None,\n                (\"Label run \" + str(set_id) + \" \"\n                 + result.get(\"mode\", \"\") + \" \"\n                 + str(result.get(\"passed\")) + \"/\"\n                 + str(result.get(\"total\")))[:200],\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify(result), 200\n");
writeNewRepair("OmniFlow-Control-Plane/portal_ai_quality.py", "def sample_quality", true,
    "\"\"\"Live AI quality sampling + human-labelled answer sets (\u00a7209).\n\nTwo complementary signals, both fail-soft and opt-in:\n\n1. **Live quality sample** - deterministic mining of recent\n   ``portal_brain_traces`` (and optional ``portal_ai_usage``) for one\n   workspace or the whole platform. Zero LLM cost. Surfaces decision mix,\n   confidence, grounding/citation share, handoff reasons, guard blocks,\n   and engine failure rate. This is the \"is the live provider behaving?\"\n   dashboard number without inventing scores.\n\n2. **Human-labelled answer sets** - owner-authored gold rows\n   (customer message + expected decision + optional expected keywords /\n   forbidden phrases). ``run_labels`` checks each row against the brain's\n   pure decision/policy gates (zero LLM by default). Optional\n   ``include_live=true`` runs one real ``portal_llm.chat_json`` call per\n   row under ``usage_scope(\"ai_quality_label\", ...)`` so cost is visible\n   and gated by the existing AI daily-cap / kill switch. Labels never\n   auto-send customer messages.\n\nLaws: no second chatbot, no background worker, no fake pass rates, no\ncustomer PII required to create a set. Tenant-scoped owner API; platform\nadmin can sample across workspaces. Defaults empty / OFF.\n\"\"\"\n\nfrom __future__ import annotations\n\nimport json\nimport logging\nimport os\nimport re\nfrom datetime import datetime, timezone\nfrom typing import Any, Dict, List, Optional, Tuple\n\nfrom flask import Blueprint, jsonify, request\n\nimport portal_db\nfrom portal_auth import (\n    PortalAuthUnavailable,\n    authenticate_portal_request,\n    ensure_human_principal,\n)\n\nlogger = logging.getLogger(\"omniflow.portal-ai-quality\")\n\nbp = Blueprint(\"portal_ai_quality\", __name__, url_prefix=\"/api/v1/portal\")\n\nLABELS_TABLE = \"portal_ai_label_sets\"\n_DDL_READY = False\n\nDEFAULT_DAYS = int(os.environ.get(\"OF_AI_QUALITY_DAYS\", \"7\") or 7)\nSAMPLE_MAX = int(os.environ.get(\"OF_AI_QUALITY_SAMPLE_MAX\", \"500\") or 500)\nMAX_SETS = int(os.environ.get(\"OF_AI_LABEL_SETS_MAX\", \"20\") or 20)\nMAX_ITEMS = int(os.environ.get(\"OF_AI_LABEL_ITEMS_MAX\", \"40\") or 40)\nMAX_NAME = 80\nMAX_MESSAGE = int(os.environ.get(\"OF_AI_LABEL_MSG_MAX\", \"500\") or 500)\nMAX_NOTE = 200\nALLOWED_DECISIONS = (\"send\", \"handoff\", \"draft\")\nLIVE_MAX_TOKENS = int(os.environ.get(\"OF_AI_QUALITY_LIVE_MAX_TOKENS\", \"80\") or 80)\n\n_DDL = \"\"\"\nCREATE TABLE IF NOT EXISTS portal_ai_label_sets (\n  id BIGSERIAL PRIMARY KEY,\n  client_id BIGINT NOT NULL,\n  name TEXT NOT NULL DEFAULT '',\n  notes TEXT NOT NULL DEFAULT '',\n  items JSONB NOT NULL DEFAULT '[]'::jsonb,\n  is_active BOOLEAN NOT NULL DEFAULT TRUE,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()\n);\nCREATE INDEX IF NOT EXISTS idx_portal_ai_label_sets\n  ON portal_ai_label_sets (client_id, is_active, id DESC);\n\"\"\"\n\n\ndef _ensure_ddl(cur) -> None:\n    global _DDL_READY\n    if _DDL_READY:\n        return\n    cur.execute(_DDL)\n    _DDL_READY = True\n\n\ndef _principal_or_error():\n    try:\n        principal = authenticate_portal_request()\n    except PortalAuthUnavailable as error:\n        return None, (jsonify({\"error\": {\"code\": \"portal_unavailable\",\n                                         \"message\": str(error)}}), 503)\n    if principal is None:\n        return None, (jsonify({\"error\": {\"code\": \"unauthorized\",\n                                         \"message\": \"Sign in required.\"}}),\n                      401)\n    return principal, None\n\n\ndef _days(value: Any) -> int:\n    try:\n        days = int(value)\n    except Exception:\n        days = DEFAULT_DAYS\n    if days not in (1, 7, 14, 30):\n        days = DEFAULT_DAYS\n    return days\n\n\ndef _clamp_sample(value: Any) -> int:\n    try:\n        n = int(value)\n    except Exception:\n        n = SAMPLE_MAX\n    return max(20, min(SAMPLE_MAX, n))\n\n\n# ---------------------------------------------------------------------------\n# Live quality sample (traces)\n# ---------------------------------------------------------------------------\n\n\ndef _parse_grounding(raw: Any) -> Dict[str, Any]:\n    if isinstance(raw, str):\n        try:\n            raw = json.loads(raw or \"{}\")\n        except Exception:\n            raw = {}\n    return raw if isinstance(raw, dict) else {}\n\n\ndef sample_quality(cur, client_id: Optional[int], days: int = DEFAULT_DAYS,\n                   limit: int = SAMPLE_MAX) -> Dict[str, Any]:\n    \"\"\"Deterministic quality snapshot over brain traces (+ usage if present).\n\n    ``client_id=None`` = platform-wide (admin). Never raises past the caller;\n    missing tables blank only the affected block.\n    \"\"\"\n    days = _days(days)\n    limit = _clamp_sample(limit)\n    out: Dict[str, Any] = {\n        \"days\": days,\n        \"generated_at\": datetime.now(timezone.utc).isoformat(),\n        \"scope\": \"workspace\" if client_id else \"platform\",\n        \"client_id\": client_id,\n        \"traces\": {\n            \"total\": 0, \"by_decision\": {}, \"by_kind\": {},\n            \"avg_confidence\": None, \"grounded_share\": None,\n            \"cited_share\": None, \"auto_reply_blocked_share\": None,\n            \"guard_blocked\": 0, \"handoff_reasons\": {},\n            \"sample\": [],\n        },\n        \"usage\": None,\n        \"signals\": [],\n    }\n\n    # --- traces ---\n    try:\n        sql = (\n            \"SELECT id, client_id, conversation_id, kind, decision, grounding,\"\n            \" created_at FROM \" + portal_db._q(\"portal_brain_traces\") +\n            \" WHERE created_at >= NOW() - (%s || ' days')::interval\"\n        )\n        params: List[Any] = [str(days)]\n        if client_id is not None:\n            sql += \" AND client_id = %s\"\n            params.append(int(client_id))\n        sql += \" ORDER BY id DESC LIMIT %s\"\n        params.append(limit)\n        cur.execute(sql, tuple(params))\n        rows = portal_db.rows(cur)\n    except Exception as error:\n        logger.warning(\"ai quality traces failed: %s\", error)\n        rows = []\n        out[\"signals\"].append({\n            \"key\": \"traces_unavailable\",\n            \"severity\": \"info\",\n            \"title\": \"Brain traces not readable yet\",\n            \"detail\": \"Quality sampling needs portal_brain_traces. \"\n                      \"It appears after the assistant answers a few chats.\",\n        })\n\n    confidences: List[float] = []\n    grounded = 0\n    cited = 0\n    auto_blocked = 0\n    guard_blocked = 0\n    by_decision: Dict[str, int] = {}\n    by_kind: Dict[str, int] = {}\n    reasons: Dict[str, int] = {}\n    sample_rows: List[Dict[str, Any]] = []\n\n    for row in rows:\n        decision = str(row.get(\"decision\") or \"handoff\")\n        kind = str(row.get(\"kind\") or \"draft\")\n        by_decision[decision] = by_decision.get(decision, 0) + 1\n        by_kind[kind] = by_kind.get(kind, 0) + 1\n        g = _parse_grounding(row.get(\"grounding\"))\n        conf = g.get(\"confidence\")\n        try:\n            if conf is not None:\n                confidences.append(float(conf))\n        except Exception:\n            pass\n        if g.get(\"grounded\") is True or g.get(\"kb_hit\") is True:\n            grounded += 1\n        if g.get(\"cited\") is True or (g.get(\"citations\") or g.get(\"sources\")):\n            cited += 1\n        if g.get(\"agent_auto_reply\") is False:\n            auto_blocked += 1\n        if g.get(\"guard_blocked\") or g.get(\"guard_level\") in (\"high\", \"block\"):\n            guard_blocked += 1\n        reason = str(g.get(\"reason\") or g.get(\"handoff_reason\") or \"\").strip()\n        if decision == \"handoff\" and reason:\n            reasons[reason] = reasons.get(reason, 0) + 1\n        if len(sample_rows) < 12:\n            sample_rows.append({\n                \"id\": int(row.get(\"id\") or 0),\n                \"client_id\": int(row.get(\"client_id\") or 0),\n                \"conversation_id\": row.get(\"conversation_id\"),\n                \"kind\": kind,\n                \"decision\": decision,\n                \"confidence\": confidences[-1] if confidences and conf is not None else None,\n                \"created_at\": str(row.get(\"created_at\") or \"\"),\n            })\n\n    total = len(rows)\n    tr = out[\"traces\"]\n    tr[\"total\"] = total\n    tr[\"by_decision\"] = by_decision\n    tr[\"by_kind\"] = by_kind\n    tr[\"avg_confidence\"] = (\n        round(sum(confidences) / len(confidences), 3) if confidences else None\n    )\n    if total:\n        tr[\"grounded_share\"] = round(grounded / total, 3)\n        tr[\"cited_share\"] = round(cited / total, 3)\n        tr[\"auto_reply_blocked_share\"] = round(auto_blocked / total, 3)\n    tr[\"guard_blocked\"] = guard_blocked\n    tr[\"handoff_reasons\"] = dict(\n        sorted(reasons.items(), key=lambda kv: (-kv[1], kv[0]))[:8]\n    )\n    tr[\"sample\"] = sample_rows\n\n    # --- usage (optional) ---\n    try:\n        sql_u = (\n            \"SELECT COUNT(*) AS calls,\"\n            \" COALESCE(SUM(CASE WHEN ok IS FALSE THEN 1 ELSE 0 END), 0) AS failed,\"\n            \" COALESCE(AVG(latency_ms), 0) AS avg_latency_ms\"\n            \" FROM \" + portal_db._q(\"portal_ai_usage\") +\n            \" WHERE created_at >= NOW() - (%s || ' days')::interval\"\n        )\n        params_u: List[Any] = [str(days)]\n        if client_id is not None:\n            sql_u += \" AND client_id = %s\"\n            params_u.append(int(client_id))\n        cur.execute(sql_u, tuple(params_u))\n        urows = portal_db.rows(cur)\n        u = urows[0] if urows else {}\n        calls = int(u.get(\"calls\") or 0)\n        failed = int(u.get(\"failed\") or 0)\n        out[\"usage\"] = {\n            \"calls\": calls,\n            \"failed\": failed,\n            \"fail_share\": round(failed / calls, 3) if calls else None,\n            \"avg_latency_ms\": int(float(u.get(\"avg_latency_ms\") or 0)),\n        }\n    except Exception as error:\n        logger.warning(\"ai quality usage failed: %s\", error)\n        out[\"usage\"] = None\n\n    # --- signals (deterministic thresholds, thin-data quiet) ---\n    signals = out[\"signals\"]\n    if total == 0 and not any(s.get(\"key\") == \"traces_unavailable\" for s in signals):\n        signals.append({\n            \"key\": \"thin_data\",\n            \"severity\": \"info\",\n            \"title\": \"Not enough AI activity yet\",\n            \"detail\": \"Quality sampling needs recent brain answers. \"\n                      \"Try again after the assistant handles a few chats.\",\n        })\n    if total >= 10:\n        handoff = by_decision.get(\"handoff\", 0)\n        handoff_share = handoff / total\n        if handoff_share >= 0.45:\n            signals.append({\n                \"key\": \"handoff_high\",\n                \"severity\": \"warn\" if handoff_share < 0.7 else \"critical\",\n                \"title\": \"Handoff rate is elevated\",\n                \"detail\": (\n                    str(round(handoff_share * 100)) + \"% of recent brain \"\n                    \"decisions handed off to a human (\" + str(handoff) +\n                    \" of \" + str(total) + \").\"\n                ),\n            })\n        if confidences and (sum(confidences) / len(confidences)) < 0.55:\n            signals.append({\n                \"key\": \"confidence_low\",\n                \"severity\": \"warn\",\n                \"title\": \"Average confidence is low\",\n                \"detail\": \"Mean confidence \"\n                          + str(out[\"traces\"][\"avg_confidence\"])\n                          + \" over \" + str(len(confidences)) + \" scored answers.\",\n            })\n        if guard_blocked >= 3:\n            signals.append({\n                \"key\": \"guard_blocks\",\n                \"severity\": \"info\",\n                \"title\": \"Prompt-injection guard blocked replies\",\n                \"detail\": str(guard_blocked) + \" recent traces marked guard-blocked.\",\n            })\n    usage = out.get(\"usage\") or {}\n    if usage.get(\"calls\", 0) >= 10 and (usage.get(\"fail_share\") or 0) >= 0.15:\n        signals.append({\n            \"key\": \"provider_fail_high\",\n            \"severity\": \"critical\" if usage[\"fail_share\"] >= 0.3 else \"warn\",\n            \"title\": \"Live provider failures are elevated\",\n            \"detail\": (\n                str(round((usage[\"fail_share\"] or 0) * 100)) + \"% of LLM calls \"\n                \"failed in the window (\" + str(usage.get(\"failed\")) + \" of \"\n                + str(usage.get(\"calls\")) + \").\"\n            ),\n        })\n    out[\"signals\"] = signals\n    return out\n\n\n# ---------------------------------------------------------------------------\n# Label sets\n# ---------------------------------------------------------------------------\n\n\ndef _clean_item(raw: Any) -> Optional[Dict[str, Any]]:\n    if not isinstance(raw, dict):\n        return None\n    message = str(raw.get(\"message\") or raw.get(\"customer_message\") or \"\").strip()\n    if not message or len(message) > MAX_MESSAGE:\n        return None\n    decision = str(raw.get(\"expected_decision\") or raw.get(\"decision\") or \"send\").strip().lower()\n    if decision not in ALLOWED_DECISIONS:\n        decision = \"send\"\n    keywords: List[str] = []\n    for key in (\"expected_keywords\", \"keywords\"):\n        val = raw.get(key)\n        if isinstance(val, list):\n            for item in val:\n                text = str(item or \"\").strip().lower()\n                if text and text not in keywords:\n                    keywords.append(text[:40])\n        elif isinstance(val, str) and val.strip():\n            for part in re.split(r\"[,;|]\", val):\n                text = part.strip().lower()\n                if text and text not in keywords:\n                    keywords.append(text[:40])\n    forbidden: List[str] = []\n    for key in (\"forbidden_phrases\", \"forbidden\"):\n        val = raw.get(key)\n        if isinstance(val, list):\n            for item in val:\n                text = str(item or \"\").strip().lower()\n                if text and text not in forbidden:\n                    forbidden.append(text[:60])\n        elif isinstance(val, str) and val.strip():\n            for part in re.split(r\"[,;|]\", val):\n                text = part.strip().lower()\n                if text and text not in forbidden:\n                    forbidden.append(text[:60])\n    note = str(raw.get(\"note\") or \"\").strip()[:MAX_NOTE]\n    return {\n        \"message\": message[:MAX_MESSAGE],\n        \"expected_decision\": decision,\n        \"expected_keywords\": keywords[:12],\n        \"forbidden_phrases\": forbidden[:12],\n        \"note\": note,\n    }\n\n\ndef _normalize_items(raw: Any) -> List[Dict[str, Any]]:\n    if isinstance(raw, str):\n        try:\n            raw = json.loads(raw)\n        except Exception:\n            raw = []\n    if not isinstance(raw, list):\n        return []\n    out: List[Dict[str, Any]] = []\n    for item in raw[:MAX_ITEMS]:\n        clean = _clean_item(item)\n        if clean:\n            out.append(clean)\n    return out\n\n\ndef _shape_set(row: Dict[str, Any]) -> Dict[str, Any]:\n    items = _normalize_items(row.get(\"items\"))\n    return {\n        \"id\": int(row.get(\"id\") or 0),\n        \"name\": str(row.get(\"name\") or \"\"),\n        \"notes\": str(row.get(\"notes\") or \"\"),\n        \"items\": items,\n        \"item_count\": len(items),\n        \"is_active\": bool(row.get(\"is_active\", True)),\n        \"updated_at\": str(row.get(\"updated_at\") or \"\"),\n        \"created_at\": str(row.get(\"created_at\") or \"\"),\n    }\n\n\ndef _validate_set_payload(payload: Dict[str, Any]) -> Tuple[Optional[str], Dict[str, Any]]:\n    name = str(payload.get(\"name\") or \"\").strip()\n    if not name or len(name) > MAX_NAME:\n        return (\"name is required (max \" + str(MAX_NAME) + \" characters).\", {})\n    notes = str(payload.get(\"notes\") or \"\").strip()[:MAX_NOTE]\n    items = _normalize_items(payload.get(\"items\"))\n    if not items:\n        return (\"Add at least one labelled example (customer message + expected decision).\", {})\n    if len(items) > MAX_ITEMS:\n        return (\"A set can hold at most \" + str(MAX_ITEMS) + \" examples.\", {})\n    is_active = payload.get(\"is_active\", True)\n    if not isinstance(is_active, bool):\n        is_active = bool(is_active)\n    return None, {\n        \"name\": name[:MAX_NAME],\n        \"notes\": notes,\n        \"items\": items,\n        \"is_active\": is_active,\n    }\n\n\ndef list_sets(cur, client_id: int) -> List[Dict[str, Any]]:\n    _ensure_ddl(cur)\n    cur.execute(\n        \"SELECT id, name, notes, items, is_active, created_at, updated_at FROM \"\n        + portal_db._q(LABELS_TABLE) +\n        \" WHERE client_id = %s ORDER BY is_active DESC, id DESC LIMIT %s\",\n        (client_id, max(1, min(50, MAX_SETS * 2))),\n    )\n    return [_shape_set(row) for row in portal_db.rows(cur)]\n\n\ndef get_set(cur, client_id: int, set_id: int) -> Optional[Dict[str, Any]]:\n    _ensure_ddl(cur)\n    cur.execute(\n        \"SELECT id, name, notes, items, is_active, created_at, updated_at FROM \"\n        + portal_db._q(LABELS_TABLE) +\n        \" WHERE client_id = %s AND id = %s\",\n        (client_id, set_id),\n    )\n    rows = portal_db.rows(cur)\n    return _shape_set(rows[0]) if rows else None\n\n\ndef _decision_from_policy(message: str, expected: str) -> Tuple[str, str]:\n    \"\"\"Zero-LLM check: policy gate + trivial keyword heuristics.\n\n    Returns (actual_decision, detail). Uses portal_brain._decide when a\n    synthetic reply is built from expected keywords; otherwise defaults to\n    send for benign text and handoff when the injection guard would block.\n    \"\"\"\n    detail = \"policy\"\n    try:\n        import portal_guard\n        inspected = portal_guard.inspect(message)\n        if portal_guard.blocks(inspected, \"standard\"):\n            return \"handoff\", \"guard_blocked\"\n    except Exception:\n        pass\n\n    # Build a synthetic \"model reply\" for the policy/decide path when we\n    # only have the customer message: prefer expected keywords as a stand-in\n    # answer so forbidden-promise detection still runs on owner-supplied text.\n    synthetic_reply = message[:180]\n    try:\n        import portal_brain\n        decision, reason = portal_brain._decide(\n            {\"reply\": synthetic_reply, \"confidence\": 0.9}, {}\n        )\n        if decision == \"handoff\":\n            return \"handoff\", str(reason or \"policy_handoff\")\n    except Exception as error:\n        detail = \"decide_error:\" + type(error).__name__\n\n    # If owner expects handoff and message is short/empty of commerce signal,\n    # still allow expected-match via keyword absence - actual stays send.\n    return \"send\", detail\n\n\ndef _keywords_ok(text: str, keywords: List[str]) -> bool:\n    if not keywords:\n        return True\n    low = text.lower()\n    return all(k in low for k in keywords)\n\n\ndef _forbidden_hit(text: str, phrases: List[str]) -> Optional[str]:\n    low = text.lower()\n    for phrase in phrases:\n        if phrase and phrase in low:\n            return phrase\n    return None\n\n\ndef evaluate_item(item: Dict[str, Any], include_live: bool = False,\n                  client_id: int = 0, cur=None) -> Dict[str, Any]:\n    \"\"\"Score one labelled example. Never raises.\"\"\"\n    message = str(item.get(\"message\") or \"\")\n    expected = str(item.get(\"expected_decision\") or \"send\")\n    keywords = list(item.get(\"expected_keywords\") or [])\n    forbidden = list(item.get(\"forbidden_phrases\") or [])\n    result: Dict[str, Any] = {\n        \"message\": message[:120],\n        \"expected_decision\": expected,\n        \"actual_decision\": None,\n        \"passed\": False,\n        \"mode\": \"deterministic\",\n        \"detail\": \"\",\n        \"live_reply\": None,\n        \"live_error\": None,\n    }\n    try:\n        actual, detail = _decision_from_policy(message, expected)\n        result[\"actual_decision\"] = actual\n        result[\"detail\"] = detail\n        decision_ok = actual == expected\n        # Keyword/forbidden checks apply to live reply when present, else\n        # to the customer message only for forbidden (owner sanity).\n        text_for_kw = message\n        live_reply = None\n        if include_live:\n            result[\"mode\"] = \"live_provider\"\n            try:\n                import portal_llm\n                system = (\n                    \"You are a concise commerce assistant. Reply in the \"\n                    \"customer's language. Return JSON \"\n                    \"{\\\"reply\\\": string, \\\"decision\\\": \\\"send\\\"|\\\"handoff\\\", \"\n                    \"\\\"confidence\\\": number}.\"\n                )\n                user = \"Customer message:\\\\n\" + message[:MAX_MESSAGE]\n                scope_cm = None\n                try:\n                    scope_cm = portal_llm.usage_scope(\n                        \"ai_quality_label\", int(client_id or 0), cur\n                    )\n                    scope_cm.__enter__()\n                except Exception:\n                    scope_cm = None\n                try:\n                    live = portal_llm.chat_json(system, user, max_tokens=LIVE_MAX_TOKENS)\n                finally:\n                    if scope_cm is not None:\n                        try:\n                            scope_cm.__exit__(None, None, None)\n                        except Exception:\n                            pass\n                if not isinstance(live, dict):\n                    result[\"live_error\"] = \"provider_unavailable_or_empty\"\n                    result[\"passed\"] = False\n                    result[\"detail\"] = \"live_call_failed\"\n                    return result\n                live_reply = str(live.get(\"reply\") or live.get(\"message\") or \"\")[:300]\n                live_decision = str(live.get(\"decision\") or \"\").strip().lower()\n                if live_decision not in ALLOWED_DECISIONS:\n                    # Fall back to policy on the live reply text.\n                    try:\n                        import portal_brain\n                        live_decision, _r = portal_brain._decide(\n                            {\"reply\": live_reply or message, \"confidence\": float(live.get(\"confidence\") or 0.5)},\n                            {},\n                        )\n                    except Exception:\n                        live_decision = \"send\"\n                result[\"actual_decision\"] = live_decision\n                result[\"live_reply\"] = live_reply\n                text_for_kw = live_reply or message\n                decision_ok = live_decision == expected\n                detail = \"live\"\n            except Exception as error:\n                result[\"live_error\"] = type(error).__name__ + \": \" + str(error)[:120]\n                result[\"passed\"] = False\n                result[\"detail\"] = \"live_exception\"\n                return result\n\n        kw_ok = _keywords_ok(text_for_kw, keywords) if (include_live and live_reply) else True\n        # When not live, keyword check is informational only on message if\n        # owner listed keywords that should appear in a good answer - skip hard fail.\n        if include_live and live_reply and keywords and not kw_ok:\n            result[\"passed\"] = False\n            result[\"detail\"] = \"missing_keywords\"\n            return result\n        hit = _forbidden_hit(text_for_kw, forbidden)\n        if hit:\n            result[\"passed\"] = False\n            result[\"detail\"] = \"forbidden:\" + hit\n            return result\n        # Non-live: decision match is the contract (guard/policy).\n        result[\"passed\"] = bool(decision_ok)\n        if not decision_ok:\n            result[\"detail\"] = \"decision_mismatch:\" + str(result[\"actual_decision\"])\n        else:\n            result[\"detail\"] = detail or \"ok\"\n        return result\n    except Exception as error:\n        result[\"detail\"] = type(error).__name__ + \": \" + str(error)[:120]\n        result[\"passed\"] = False\n        return result\n\n\ndef run_labels(cur, client_id: int, set_id: int,\n               include_live: bool = False) -> Dict[str, Any]:\n    label_set = get_set(cur, client_id, set_id)\n    if label_set is None:\n        return {\"error\": \"not_found\"}\n    if not label_set.get(\"is_active\", True):\n        return {\"error\": \"inactive\", \"set\": label_set}\n    items = label_set.get(\"items\") or []\n    results = [evaluate_item(item, include_live=include_live,\n                             client_id=client_id, cur=cur) for item in items]\n    passed = sum(1 for r in results if r.get(\"passed\"))\n    total = len(results)\n    score = round((passed / total) * 100, 1) if total else 0.0\n    return {\n        \"set_id\": set_id,\n        \"name\": label_set.get(\"name\"),\n        \"mode\": \"live_provider\" if include_live else \"deterministic\",\n        \"llm_calls\": total if include_live else 0,\n        \"passed\": passed,\n        \"total\": total,\n        \"score\": score,\n        \"status\": \"pass\" if total and passed == total else (\"empty\" if not total else \"fail\"),\n        \"results\": results,\n        \"generated_at\": datetime.now(timezone.utc).isoformat(),\n    }\n\n\n# ---------------------------------------------------------------------------\n# Owner HTTP API\n# ---------------------------------------------------------------------------\n\n\n@bp.get(\"/ai/quality\")\ndef get_quality():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    client_id = int(principal.get(\"client_id\") or 0)\n    days = _days(request.args.get(\"days\"))\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            data = sample_quality(cur, client_id, days=days)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify(data), 200\n\n\n@bp.get(\"/ai/labels\")\ndef get_labels():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            sets = list_sets(cur, client_id)\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\n        \"sets\": sets,\n        \"limits\": {\"max_sets\": MAX_SETS, \"max_items\": MAX_ITEMS,\n                   \"max_message\": MAX_MESSAGE},\n        \"decisions\": list(ALLOWED_DECISIONS),\n    }), 200\n\n\n@bp.post(\"/ai/labels\")\ndef create_label_set():\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    problem, clean = _validate_set_payload(payload)\n    if problem:\n        return jsonify({\"error\": {\"code\": \"bad_request\", \"message\": problem}}), 400\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"SELECT COUNT(*) AS total FROM \" + portal_db._q(LABELS_TABLE) +\n                \" WHERE client_id = %s\",\n                (client_id,),\n            )\n            rows = portal_db.rows(cur)\n            if int((rows[0] if rows else {}).get(\"total\") or 0) >= MAX_SETS:\n                return jsonify({\"error\": {\n                    \"code\": \"bad_request\",\n                    \"message\": \"Max \" + str(MAX_SETS) + \" label sets.\"}}), 400\n            cur.execute(\n                \"INSERT INTO \" + portal_db._q(LABELS_TABLE) +\n                \" (client_id, name, notes, items, is_active)\"\n                \" VALUES (%s, %s, %s, CAST(%s AS JSONB), %s) RETURNING id\",\n                (client_id, clean[\"name\"], clean[\"notes\"],\n                 json.dumps(clean[\"items\"], ensure_ascii=False),\n                 clean[\"is_active\"]),\n            )\n            rows = portal_db.rows(cur)\n            set_id = int((rows[0] if rows else {}).get(\"id\") or 0)\n            portal_db.log_action(\n                cur, client_id, \"ai.labels_saved\", \"customer_user\",\n                principal.get(\"user_id\"), None,\n                (\"Label set created: \" + clean[\"name\"])[:200],\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True, \"set\": {\n        \"id\": set_id, \"name\": clean[\"name\"], \"notes\": clean[\"notes\"],\n        \"items\": clean[\"items\"], \"item_count\": len(clean[\"items\"]),\n        \"is_active\": clean[\"is_active\"],\n    }}), 200\n\n\n@bp.put(\"/ai/labels/<int:set_id>\")\ndef update_label_set(set_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    problem, clean = _validate_set_payload(payload)\n    if problem:\n        return jsonify({\"error\": {\"code\": \"bad_request\", \"message\": problem}}), 400\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"UPDATE \" + portal_db._q(LABELS_TABLE) +\n                \" SET name = %s, notes = %s, items = CAST(%s AS JSONB),\"\n                \" is_active = %s, updated_at = NOW()\"\n                \" WHERE id = %s AND client_id = %s RETURNING id\",\n                (clean[\"name\"], clean[\"notes\"],\n                 json.dumps(clean[\"items\"], ensure_ascii=False),\n                 clean[\"is_active\"], set_id, client_id),\n            )\n            rows = portal_db.rows(cur)\n            if not rows:\n                return jsonify({\"error\": {\n                    \"code\": \"not_found\",\n                    \"message\": \"No such label set in this workspace.\"}}), 404\n            portal_db.log_action(\n                cur, client_id, \"ai.labels_saved\", \"customer_user\",\n                principal.get(\"user_id\"), None,\n                (\"Label set updated: \" + clean[\"name\"])[:200],\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.delete(\"/ai/labels/<int:set_id>\")\ndef delete_label_set(set_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    client_id = int(principal.get(\"client_id\") or 0)\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            cur.execute(\n                \"UPDATE \" + portal_db._q(LABELS_TABLE) +\n                \" SET is_active = FALSE, updated_at = NOW()\"\n                \" WHERE id = %s AND client_id = %s RETURNING id\",\n                (set_id, client_id),\n            )\n            rows = portal_db.rows(cur)\n            if not rows:\n                return jsonify({\"error\": {\n                    \"code\": \"not_found\",\n                    \"message\": \"No such label set in this workspace.\"}}), 404\n            portal_db.log_action(\n                cur, client_id, \"ai.labels_archived\", \"customer_user\",\n                principal.get(\"user_id\"), None,\n                (\"Label set archived: \" + str(set_id))[:200],\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify({\"ok\": True}), 200\n\n\n@bp.post(\"/ai/labels/<int:set_id>/run\")\ndef run_label_set(set_id: int):\n    principal, error = _principal_or_error()\n    if error:\n        return error\n    forbidden = ensure_human_principal(principal)\n    if forbidden is not None:\n        return forbidden\n    client_id = int(principal.get(\"client_id\") or 0)\n    payload = request.get_json(silent=True) or {}\n    include_live = payload.get(\"include_live\") is True\n    conn = portal_db._conn()\n    try:\n        with conn.cursor() as cur:\n            _ensure_ddl(cur)\n            result = run_labels(cur, client_id, set_id, include_live=include_live)\n            if result.get(\"error\") == \"not_found\":\n                return jsonify({\"error\": {\n                    \"code\": \"not_found\",\n                    \"message\": \"No such label set in this workspace.\"}}), 404\n            if result.get(\"error\") == \"inactive\":\n                return jsonify({\"error\": {\n                    \"code\": \"bad_request\",\n                    \"message\": \"This label set is archived.\"}}), 400\n            portal_db.log_action(\n                cur, client_id, \"ai.labels_run\", \"customer_user\",\n                principal.get(\"user_id\"), None,\n                (\"Label run \" + str(set_id) + \" \"\n                 + result.get(\"mode\", \"\") + \" \"\n                 + str(result.get(\"passed\")) + \"/\"\n                 + str(result.get(\"total\")))[:200],\n            )\n        conn.commit()\n    finally:\n        conn.close()\n    return jsonify(result), 200\n");
writeNewRepair("omniflow-backend-patch/admin_ai.py", "@bp.get(\"/quality\")", false,
    "\"\"\"Admin AI Control Center (MASTER-UPGRADE build-order 15).\n\nPlatform-admin view over EVERY workspace's AI: autonomy level, agents,\nLLM usage + estimated cost, open escalations, pending approvals, brain\nanswers vs handoffs, last AI activity - plus the platform controls the\nbrain and every LLM call obey:\n\n  * ``ai.kill_switch`` (on|off)      - pause all AI answering platform-wide\n                                       (portal_llm.chat_json returns None,\n                                       the brain runs at \"off\");\n  * ``ai.autonomy_cap`` (off|suggest|auto) - the highest autonomy any\n                                       workspace may run at (brain uses\n                                       min(own, cap));\n  * ``ai.daily_call_cap`` (int, 0 = unlimited) - LLM calls per workspace\n                                       per 24 h; the owner is notified once\n                                       a day when the cap is hit.\n\nControls live in platform_settings group \"ai\" (DB-backed, env fallback\nOF_AI_*), are saved through the existing admin providers API (validated\nwhitelist) and read through ``platform_settings.ai_controls()``. This\nmodule adds the READ overview and the per-workspace autonomy override\n(audited as actor ``platform_admin`` + owner notified). Guarded by the\nsame service/admin key as the other admin blueprints; every optional\ntable sits behind a SAVEPOINT so a fresh install still renders.\n\"\"\"\n\nimport json\nimport logging\nimport os\nimport secrets as _secrets\nfrom datetime import datetime, timezone\nfrom typing import Any, Dict, List, Optional\n\nfrom flask import Blueprint, jsonify, request\n\nimport platform_settings\nimport portal_db\n\nlogger = logging.getLogger(\"omniflow.admin-ai\")\n\nbp = Blueprint(\"admin_ai\", __name__, url_prefix=\"/api/v1/admin/ai\")\n\nDEFAULT_DAYS = 7\nMAX_DAYS = int(os.environ.get(\"OF_ADMIN_AI_MAX_DAYS\", \"90\") or 90)\nMAX_WORKSPACES = int(os.environ.get(\"OF_ADMIN_AI_MAX_WORKSPACES\", \"200\") or 200)\nRECENT_LIMIT = int(os.environ.get(\"OF_ADMIN_AI_RECENT\", \"40\") or 40)\nAUTONOMY_LEVELS = (\"off\", \"suggest\", \"auto\")\n\n\n# ---------------------------------------------------------------------------\n# auth (same contract as admin_providers / admin_users)\n# ---------------------------------------------------------------------------\n\ndef _authorized() -> bool:\n    key = request.headers.get(\"X-Omniflow-Key\", \"\")\n    if not key:\n        return False\n    accepted = [\n        os.environ.get(\"OMNIFLOW_SERVICE_KEY\"),\n        os.environ.get(\"OMNIFLOW_ADMIN_API_KEY\"),\n    ]\n    return any(k for k in accepted if k and _secrets.compare_digest(key, k))\n\n\n@bp.before_request\ndef _guard():\n    if request.method == \"OPTIONS\":\n        return None\n    if not _authorized():\n        return jsonify({\"error\": {\"code\": \"forbidden\",\n                                  \"message\": \"Service key missing or invalid.\"}}), 403\n\n\n# ---------------------------------------------------------------------------\n# helpers\n# ---------------------------------------------------------------------------\n\ndef _days(value: Any) -> int:\n    try:\n        days = int(value or DEFAULT_DAYS)\n    except (TypeError, ValueError):\n        days = DEFAULT_DAYS\n    return max(1, min(MAX_DAYS, days))\n\n\ndef _iso(value: Any) -> Optional[str]:\n    if isinstance(value, datetime):\n        if value.tzinfo is None:\n            value = value.replace(tzinfo=timezone.utc)\n        return value.isoformat()\n    return str(value) if value else None\n\n\ndef _guarded(cur, label: str, fn):\n    \"\"\"Run one optional block behind a SAVEPOINT (missing table on a\n    fresh install must not abort the overview); None on failure.\"\"\"\n    try:\n        cur.execute(\"SAVEPOINT of_admin_ai\")\n        value = fn()\n        cur.execute(\"RELEASE SAVEPOINT of_admin_ai\")\n        return value\n    except Exception as error:\n        logger.warning(\"admin ai overview %s failed: %s\", label, error)\n        try:\n            cur.execute(\"ROLLBACK TO SAVEPOINT of_admin_ai\")\n        except Exception:\n            pass\n        return None\n\n\ndef _by_client(rows: Optional[List[Dict[str, Any]]]) -> Dict[int, Dict[str, Any]]:\n    out: Dict[int, Dict[str, Any]] = {}\n    for row in rows or []:\n        try:\n            out[int(row.get(\"client_id\") or 0)] = row\n        except (TypeError, ValueError):\n            continue\n    return out\n\n\n# ---------------------------------------------------------------------------\n# overview\n# ---------------------------------------------------------------------------\n\ndef _workspaces(cur) -> List[Dict[str, Any]]:\n    email_col = getattr(portal_db, \"USER_EMAIL_COL\", \"email\")\n    cur.execute(\n        \"SELECT client_id, MIN(\" + portal_db._q(email_col) +\n        \") AS email, MIN(display_name) AS owner, COUNT(*) AS users\"\n        \" FROM \" + portal_db._q(portal_db.USERS_TABLE) +\n        \" WHERE client_id IS NOT NULL\"\n        \" GROUP BY client_id ORDER BY client_id LIMIT %s\",\n        (max(1, MAX_WORKSPACES),),\n    )\n    return portal_db.rows(cur)\n\n\ndef _names(cur) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT client_id, profile->>'business_name' AS business_name\"\n        \" FROM \" + portal_db._q(portal_db.PROFILE_TABLE),\n    )\n    return portal_db.rows(cur)\n\n\ndef _autonomy(cur) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT client_id, autonomy, updated_at FROM \" +\n        portal_db._q(\"portal_brain_settings\"),\n    )\n    return portal_db.rows(cur)\n\n\ndef _agents(cur) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT client_id, COUNT(*) AS total,\"\n        \" COUNT(*) FILTER (WHERE is_active) AS active,\"\n        \" COUNT(*) FILTER (WHERE is_active AND can_auto_reply = FALSE)\"\n        \" AS draft_only\"\n        \" FROM \" + portal_db._q(\"portal_agents\") + \" GROUP BY client_id\",\n    )\n    return portal_db.rows(cur)\n\n\ndef _usage(cur, days: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT client_id, model, COUNT(*) AS calls,\"\n        \" COUNT(*) FILTER (WHERE NOT ok) AS failed,\"\n        \" COALESCE(SUM(prompt_tokens), 0) AS prompt_tokens,\"\n        \" COALESCE(SUM(completion_tokens), 0) AS completion_tokens,\"\n        \" MAX(created_at) AS last_call_at\"\n        \" FROM \" + portal_db._q(\"portal_ai_usage\") +\n        \" WHERE created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY client_id, model\",\n        (days,),\n    )\n    return portal_db.rows(cur)\n\n\ndef _escalations(cur) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT client_id, COUNT(*) AS open FROM \" +\n        portal_db._q(\"portal_escalations\") +\n        \" WHERE status = 'open' GROUP BY client_id\",\n    )\n    return portal_db.rows(cur)\n\n\ndef _approvals(cur) -> List[Dict[str, Any]]:\n    import portal_approvals\n\n    cur.execute(\n        \"SELECT client_id, COUNT(*) AS pending FROM \" +\n        portal_db._q(portal_approvals.TABLE) +\n        \" WHERE status = 'pending' GROUP BY client_id\",\n    )\n    return portal_db.rows(cur)\n\n\ndef _traces(cur, days: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT client_id, decision,\"\n        \" (COALESCE(grounding->>'reason', '') = 'injection_suspected')\"\n        \" AS blocked, COUNT(*) AS n FROM \" +\n        portal_db._q(\"portal_brain_traces\") +\n        \" WHERE kind = 'ingest_answer'\"\n        \" AND created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY client_id, decision, blocked\",\n        (days,),\n    )\n    return portal_db.rows(cur)\n\n\ndef _recent(cur, days: int) -> List[Dict[str, Any]]:\n    import portal_ai_audit\n\n    cur.execute(\n        \"SELECT id, client_id, action, actor_kind, conversation_id, note,\"\n        \" created_at FROM \" + portal_db._q(portal_ai_audit.LOG_TABLE) +\n        \" WHERE created_at > NOW() - make_interval(days => %s)\"\n        \" AND (actor_kind = ANY(%s) OR action LIKE ANY(%s))\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (days, list(portal_ai_audit.AI_ACTOR_KINDS),\n         portal_ai_audit._patterns(), max(1, RECENT_LIMIT)),\n    )\n    return portal_db.rows(cur)\n\n\ndef overview(cur, days: int = DEFAULT_DAYS) -> Dict[str, Any]:\n    \"\"\"Every workspace's AI posture + platform totals (read-only).\"\"\"\n    days = _days(days)\n    import portal_ai_usage\n    import portal_ai_audit\n\n    workspaces = _guarded(cur, \"workspaces\", lambda: _workspaces(cur)) or []\n    names = _by_client(_guarded(cur, \"names\", lambda: _names(cur)))\n    autonomy = _by_client(_guarded(cur, \"autonomy\", lambda: _autonomy(cur)))\n    agents = _by_client(_guarded(cur, \"agents\", lambda: _agents(cur)))\n    usage_rows = _guarded(cur, \"usage\", lambda: _usage(cur, days)) or []\n    escalations = _by_client(_guarded(cur, \"escalations\",\n                                      lambda: _escalations(cur)))\n    approvals = _by_client(_guarded(cur, \"approvals\", lambda: _approvals(cur)))\n    trace_rows = _guarded(cur, \"traces\", lambda: _traces(cur, days)) or []\n    recent_rows = _guarded(cur, \"recent\", lambda: _recent(cur, days)) or []\n\n    price_table = portal_ai_usage.prices()\n    usage: Dict[int, Dict[str, Any]] = {}\n    for row in usage_rows:\n        cid = int(row.get(\"client_id\") or 0)\n        entry = usage.setdefault(cid, {\"calls\": 0, \"failed\": 0, \"tokens\": 0,\n                                       \"cost_usd\": 0.0, \"priced\": False,\n                                       \"last_call_at\": None})\n        prompt = int(row.get(\"prompt_tokens\") or 0)\n        completion = int(row.get(\"completion_tokens\") or 0)\n        entry[\"calls\"] += int(row.get(\"calls\") or 0)\n        entry[\"failed\"] += int(row.get(\"failed\") or 0)\n        entry[\"tokens\"] += prompt + completion\n        cost = portal_ai_usage.estimate_cost(\n            str(row.get(\"model\") or \"\"), prompt, completion, price_table)\n        if cost is not None:\n            entry[\"cost_usd\"] = round(entry[\"cost_usd\"] + cost, 4)\n            entry[\"priced\"] = True\n        last = row.get(\"last_call_at\")\n        if last and (entry[\"last_call_at\"] is None\n                     or _iso(last) > str(entry[\"last_call_at\"])):\n            entry[\"last_call_at\"] = _iso(last)\n\n    traces: Dict[int, Dict[str, int]] = {}\n    for row in trace_rows:\n        cid = int(row.get(\"client_id\") or 0)\n        entry = traces.setdefault(cid, {\"answers\": 0, \"handoffs\": 0,\n                                        \"blocked\": 0})\n        if str(row.get(\"decision\") or \"\") == \"send\":\n            entry[\"answers\"] += int(row.get(\"n\") or 0)\n        else:\n            entry[\"handoffs\"] += int(row.get(\"n\") or 0)\n            if row.get(\"blocked\") is True:\n                entry[\"blocked\"] += int(row.get(\"n\") or 0)\n\n    # Universe: every workspace with users, plus any workspace that shows\n    # AI activity but no user row (never hide activity).\n    known = {int(w.get(\"client_id\") or 0) for w in workspaces}\n    extra = (set(usage) | set(autonomy) | set(agents)) - known - {0}\n    for cid in sorted(extra):\n        workspaces.append({\"client_id\": cid, \"email\": \"\", \"owner\": \"\",\n                           \"users\": 0})\n\n    items: List[Dict[str, Any]] = []\n    totals = {\"workspaces\": 0, \"auto\": 0, \"suggest\": 0, \"off\": 0,\n              \"agents_active\": 0, \"calls\": 0, \"failed\": 0, \"tokens\": 0,\n              \"cost_usd\": 0.0, \"priced\": bool(price_table),\n              \"open_escalations\": 0, \"pending_approvals\": 0,\n              \"answers\": 0, \"handoffs\": 0, \"blocked\": 0}\n    for ws in workspaces:\n        cid = int(ws.get(\"client_id\") or 0)\n        if cid <= 0:\n            continue\n        level = str((autonomy.get(cid) or {}).get(\"autonomy\") or \"suggest\")\n        if level not in AUTONOMY_LEVELS:\n            level = \"suggest\"\n        use = usage.get(cid) or {\"calls\": 0, \"failed\": 0, \"tokens\": 0,\n                                 \"cost_usd\": 0.0, \"priced\": False,\n                                 \"last_call_at\": None}\n        agent = agents.get(cid) or {}\n        trace = traces.get(cid) or {\"answers\": 0, \"handoffs\": 0,\n                                    \"blocked\": 0}\n        item = {\n            \"client_id\": cid,\n            \"name\": str((names.get(cid) or {}).get(\"business_name\") or \"\"),\n            \"owner\": str(ws.get(\"owner\") or \"\"),\n            \"email\": str(ws.get(\"email\") or \"\"),\n            \"users\": int(ws.get(\"users\") or 0),\n            \"autonomy\": level,\n            \"autonomy_updated_at\": _iso((autonomy.get(cid) or {}).get(\n                \"updated_at\")),\n            \"agents_active\": int(agent.get(\"active\") or 0),\n            \"agents_total\": int(agent.get(\"total\") or 0),\n            \"agents_draft_only\": int(agent.get(\"draft_only\") or 0),\n            \"calls\": int(use[\"calls\"]),\n            \"failed\": int(use[\"failed\"]),\n            \"tokens\": int(use[\"tokens\"]),\n            \"cost_usd\": (round(float(use[\"cost_usd\"]), 4)\n                         if use.get(\"priced\") else None),\n            \"last_call_at\": use.get(\"last_call_at\"),\n            \"open_escalations\": int((escalations.get(cid) or {}).get(\n                \"open\") or 0),\n            \"pending_approvals\": int((approvals.get(cid) or {}).get(\n                \"pending\") or 0),\n            \"answers\": int(trace[\"answers\"]),\n            \"handoffs\": int(trace[\"handoffs\"]),\n            \"blocked\": int(trace.get(\"blocked\") or 0),\n        }\n        items.append(item)\n        totals[\"workspaces\"] += 1\n        totals[level] += 1\n        totals[\"agents_active\"] += item[\"agents_active\"]\n        totals[\"calls\"] += item[\"calls\"]\n        totals[\"failed\"] += item[\"failed\"]\n        totals[\"tokens\"] += item[\"tokens\"]\n        if item[\"cost_usd\"] is not None:\n            totals[\"cost_usd\"] = round(totals[\"cost_usd\"] + item[\"cost_usd\"], 4)\n        totals[\"open_escalations\"] += item[\"open_escalations\"]\n        totals[\"pending_approvals\"] += item[\"pending_approvals\"]\n        totals[\"answers\"] += item[\"answers\"]\n        totals[\"handoffs\"] += item[\"handoffs\"]\n        totals[\"blocked\"] += item[\"blocked\"]\n    items.sort(key=lambda i: (-i[\"calls\"], i[\"client_id\"]))\n\n    recent = []\n    for row in recent_rows:\n        recent.append({\n            \"id\": int(row.get(\"id\") or 0),\n            \"client_id\": int(row.get(\"client_id\") or 0),\n            \"action\": str(row.get(\"action\") or \"\"),\n            \"category\": portal_ai_audit.categorize(\n                row.get(\"action\"), row.get(\"actor_kind\")),\n            \"actor_kind\": str(row.get(\"actor_kind\") or \"\"),\n            \"conversation_id\": (int(row[\"conversation_id\"])\n                                if row.get(\"conversation_id\") else None),\n            \"note\": str(row.get(\"note\") or \"\")[:300],\n            \"created_at\": _iso(row.get(\"created_at\")),\n        })\n\n    return {\n        \"days\": days,\n        \"generated_at\": datetime.now(timezone.utc).isoformat(),\n        \"controls\": platform_settings.ai_controls(),\n        \"totals\": totals,\n        \"workspaces\": items,\n        \"recent\": recent,\n    }\n\n\n@bp.get(\"/eval\")\ndef get_behavioral_eval():\n    \"\"\"Run the bounded, deterministic AI behavior contracts.\n\n    This intentionally makes zero provider calls and touches no tenant data;\n    it is a deploy-time smoke signal, not a customer-message evaluator.\n    \"\"\"\n    try:\n        import portal_ai_eval\n\n        return jsonify(portal_ai_eval.run_contract_suite()), 200\n    except Exception as error:\n        logger.warning(\"admin ai behavioral eval failed: %s\", error)\n        return jsonify({\"error\": {\n            \"code\": \"ai_eval_unavailable\",\n            \"message\": \"AI behavioral evaluation temporarily unavailable.\",\n        }}), 503\n\n\n\n\n@bp.get(\"/quality\")\ndef get_live_quality():\n    \"\"\"Platform-wide live quality sample over brain traces + usage.\n    Service-key only (before_request). Zero LLM cost. Optional\n    ?client_id= filters to one workspace; ?days=1|7|14|30.\"\"\"\n    try:\n        import portal_ai_quality\n        days = request.args.get(\"days\")\n        raw_client = request.args.get(\"client_id\")\n        client_id = None\n        if raw_client not in (None, \"\"):\n            try:\n                client_id = int(raw_client)\n                if client_id <= 0:\n                    client_id = None\n            except Exception:\n                client_id = None\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                data = portal_ai_quality.sample_quality(\n                    cur, client_id, days=days or portal_ai_quality.DEFAULT_DAYS\n                )\n            conn.commit()\n        finally:\n            conn.close()\n        return jsonify(data), 200\n    except Exception as error:\n        logger.warning(\"admin ai quality sample failed: %s\", error)\n        return jsonify({\"error\": {\n            \"code\": \"ai_quality_unavailable\",\n            \"message\": \"Live AI quality sampling temporarily unavailable.\",\n        }}), 503\n\n\n@bp.get(\"/overview\")\ndef get_overview():\n    days = _days(request.args.get(\"days\"))\n    try:\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                payload = overview(cur, days)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        logger.warning(\"admin ai overview failed: %s\", error)\n        return jsonify({\"error\": {\"code\": \"db_unavailable\",\n                                  \"message\": \"AI overview temporarily\"\n                                             \" unavailable.\"}}), 503\n    return jsonify(payload), 200\n\n\n# ---------------------------------------------------------------------------\n# per-workspace autonomy override\n# ---------------------------------------------------------------------------\n\ndef set_autonomy(cur, client_id: int, autonomy: str, reason: str = \"\") -> None:\n    \"\"\"Upsert one workspace's brain autonomy (platform admin override) and\n    audit it as actor ``platform_admin`` - inside the caller's transaction.\"\"\"\n    import portal_brain\n\n    portal_brain._ensure_ddl(cur)\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(portal_brain.SETTINGS_TABLE) +\n        \" (client_id, autonomy, updated_at) VALUES (%s, %s, NOW())\"\n        \" ON CONFLICT (client_id) DO UPDATE SET autonomy = EXCLUDED.autonomy,\"\n        \" updated_at = NOW()\",\n        (client_id, autonomy),\n    )\n    portal_db.log_action(\n        cur, client_id, \"brain.autonomy_override\", \"platform_admin\", None, None,\n        (\"Platform admin set AI autonomy to \" + autonomy\n         + ((\": \" + reason) if reason else \"\"))[:200],\n    )\n\n\n@bp.post(\"/clients/<int:client_id>/autonomy\")\ndef post_autonomy(client_id: int):\n    payload = request.get_json(silent=True) or {}\n    autonomy = str(payload.get(\"autonomy\") or \"\").strip().lower()\n    reason = str(payload.get(\"reason\") or \"\").strip()[:200]\n    if autonomy not in AUTONOMY_LEVELS:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"autonomy must be off, suggest\"\n                                             \" or auto.\"}}), 400\n    if client_id <= 0:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"client_id is required.\"}}), 400\n    try:\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                set_autonomy(cur, client_id, autonomy, reason)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        logger.warning(\"admin ai autonomy override failed: %s\", error)\n        return jsonify({\"error\": {\"code\": \"db_unavailable\",\n                                  \"message\": \"Could not update autonomy.\"}}), 503\n    try:\n        import portal_notify\n\n        portal_notify.notify(\n            client_id, \"system\", \"AI autonomy changed by the OmniFlow team\",\n            \"Your Business Brain now runs at autonomy '\" + autonomy + \"'.\"\n            + ((\" Reason: \" + reason) if reason else \"\")\n            + \" You can review this under Settings > AI Brain.\",\n            severity=\"high\" if autonomy == \"off\" else \"normal\",\n            dedupe_key=\"autonomy_override:\" + str(client_id) + \":\" + autonomy)\n    except Exception:\n        pass\n    return jsonify({\"ok\": True, \"client_id\": client_id,\n                    \"autonomy\": autonomy}), 200\n");
writeNewRepair("OmniFlow-Control-Plane/admin_ai.py", "@bp.get(\"/quality\")", true,
    "\"\"\"Admin AI Control Center (MASTER-UPGRADE build-order 15).\n\nPlatform-admin view over EVERY workspace's AI: autonomy level, agents,\nLLM usage + estimated cost, open escalations, pending approvals, brain\nanswers vs handoffs, last AI activity - plus the platform controls the\nbrain and every LLM call obey:\n\n  * ``ai.kill_switch`` (on|off)      - pause all AI answering platform-wide\n                                       (portal_llm.chat_json returns None,\n                                       the brain runs at \"off\");\n  * ``ai.autonomy_cap`` (off|suggest|auto) - the highest autonomy any\n                                       workspace may run at (brain uses\n                                       min(own, cap));\n  * ``ai.daily_call_cap`` (int, 0 = unlimited) - LLM calls per workspace\n                                       per 24 h; the owner is notified once\n                                       a day when the cap is hit.\n\nControls live in platform_settings group \"ai\" (DB-backed, env fallback\nOF_AI_*), are saved through the existing admin providers API (validated\nwhitelist) and read through ``platform_settings.ai_controls()``. This\nmodule adds the READ overview and the per-workspace autonomy override\n(audited as actor ``platform_admin`` + owner notified). Guarded by the\nsame service/admin key as the other admin blueprints; every optional\ntable sits behind a SAVEPOINT so a fresh install still renders.\n\"\"\"\n\nimport json\nimport logging\nimport os\nimport secrets as _secrets\nfrom datetime import datetime, timezone\nfrom typing import Any, Dict, List, Optional\n\nfrom flask import Blueprint, jsonify, request\n\nimport platform_settings\nimport portal_db\n\nlogger = logging.getLogger(\"omniflow.admin-ai\")\n\nbp = Blueprint(\"admin_ai\", __name__, url_prefix=\"/api/v1/admin/ai\")\n\nDEFAULT_DAYS = 7\nMAX_DAYS = int(os.environ.get(\"OF_ADMIN_AI_MAX_DAYS\", \"90\") or 90)\nMAX_WORKSPACES = int(os.environ.get(\"OF_ADMIN_AI_MAX_WORKSPACES\", \"200\") or 200)\nRECENT_LIMIT = int(os.environ.get(\"OF_ADMIN_AI_RECENT\", \"40\") or 40)\nAUTONOMY_LEVELS = (\"off\", \"suggest\", \"auto\")\n\n\n# ---------------------------------------------------------------------------\n# auth (same contract as admin_providers / admin_users)\n# ---------------------------------------------------------------------------\n\ndef _authorized() -> bool:\n    key = request.headers.get(\"X-Omniflow-Key\", \"\")\n    if not key:\n        return False\n    accepted = [\n        os.environ.get(\"OMNIFLOW_SERVICE_KEY\"),\n        os.environ.get(\"OMNIFLOW_ADMIN_API_KEY\"),\n    ]\n    return any(k for k in accepted if k and _secrets.compare_digest(key, k))\n\n\n@bp.before_request\ndef _guard():\n    if request.method == \"OPTIONS\":\n        return None\n    if not _authorized():\n        return jsonify({\"error\": {\"code\": \"forbidden\",\n                                  \"message\": \"Service key missing or invalid.\"}}), 403\n\n\n# ---------------------------------------------------------------------------\n# helpers\n# ---------------------------------------------------------------------------\n\ndef _days(value: Any) -> int:\n    try:\n        days = int(value or DEFAULT_DAYS)\n    except (TypeError, ValueError):\n        days = DEFAULT_DAYS\n    return max(1, min(MAX_DAYS, days))\n\n\ndef _iso(value: Any) -> Optional[str]:\n    if isinstance(value, datetime):\n        if value.tzinfo is None:\n            value = value.replace(tzinfo=timezone.utc)\n        return value.isoformat()\n    return str(value) if value else None\n\n\ndef _guarded(cur, label: str, fn):\n    \"\"\"Run one optional block behind a SAVEPOINT (missing table on a\n    fresh install must not abort the overview); None on failure.\"\"\"\n    try:\n        cur.execute(\"SAVEPOINT of_admin_ai\")\n        value = fn()\n        cur.execute(\"RELEASE SAVEPOINT of_admin_ai\")\n        return value\n    except Exception as error:\n        logger.warning(\"admin ai overview %s failed: %s\", label, error)\n        try:\n            cur.execute(\"ROLLBACK TO SAVEPOINT of_admin_ai\")\n        except Exception:\n            pass\n        return None\n\n\ndef _by_client(rows: Optional[List[Dict[str, Any]]]) -> Dict[int, Dict[str, Any]]:\n    out: Dict[int, Dict[str, Any]] = {}\n    for row in rows or []:\n        try:\n            out[int(row.get(\"client_id\") or 0)] = row\n        except (TypeError, ValueError):\n            continue\n    return out\n\n\n# ---------------------------------------------------------------------------\n# overview\n# ---------------------------------------------------------------------------\n\ndef _workspaces(cur) -> List[Dict[str, Any]]:\n    email_col = getattr(portal_db, \"USER_EMAIL_COL\", \"email\")\n    cur.execute(\n        \"SELECT client_id, MIN(\" + portal_db._q(email_col) +\n        \") AS email, MIN(display_name) AS owner, COUNT(*) AS users\"\n        \" FROM \" + portal_db._q(portal_db.USERS_TABLE) +\n        \" WHERE client_id IS NOT NULL\"\n        \" GROUP BY client_id ORDER BY client_id LIMIT %s\",\n        (max(1, MAX_WORKSPACES),),\n    )\n    return portal_db.rows(cur)\n\n\ndef _names(cur) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT client_id, profile->>'business_name' AS business_name\"\n        \" FROM \" + portal_db._q(portal_db.PROFILE_TABLE),\n    )\n    return portal_db.rows(cur)\n\n\ndef _autonomy(cur) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT client_id, autonomy, updated_at FROM \" +\n        portal_db._q(\"portal_brain_settings\"),\n    )\n    return portal_db.rows(cur)\n\n\ndef _agents(cur) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT client_id, COUNT(*) AS total,\"\n        \" COUNT(*) FILTER (WHERE is_active) AS active,\"\n        \" COUNT(*) FILTER (WHERE is_active AND can_auto_reply = FALSE)\"\n        \" AS draft_only\"\n        \" FROM \" + portal_db._q(\"portal_agents\") + \" GROUP BY client_id\",\n    )\n    return portal_db.rows(cur)\n\n\ndef _usage(cur, days: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT client_id, model, COUNT(*) AS calls,\"\n        \" COUNT(*) FILTER (WHERE NOT ok) AS failed,\"\n        \" COALESCE(SUM(prompt_tokens), 0) AS prompt_tokens,\"\n        \" COALESCE(SUM(completion_tokens), 0) AS completion_tokens,\"\n        \" MAX(created_at) AS last_call_at\"\n        \" FROM \" + portal_db._q(\"portal_ai_usage\") +\n        \" WHERE created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY client_id, model\",\n        (days,),\n    )\n    return portal_db.rows(cur)\n\n\ndef _escalations(cur) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT client_id, COUNT(*) AS open FROM \" +\n        portal_db._q(\"portal_escalations\") +\n        \" WHERE status = 'open' GROUP BY client_id\",\n    )\n    return portal_db.rows(cur)\n\n\ndef _approvals(cur) -> List[Dict[str, Any]]:\n    import portal_approvals\n\n    cur.execute(\n        \"SELECT client_id, COUNT(*) AS pending FROM \" +\n        portal_db._q(portal_approvals.TABLE) +\n        \" WHERE status = 'pending' GROUP BY client_id\",\n    )\n    return portal_db.rows(cur)\n\n\ndef _traces(cur, days: int) -> List[Dict[str, Any]]:\n    cur.execute(\n        \"SELECT client_id, decision,\"\n        \" (COALESCE(grounding->>'reason', '') = 'injection_suspected')\"\n        \" AS blocked, COUNT(*) AS n FROM \" +\n        portal_db._q(\"portal_brain_traces\") +\n        \" WHERE kind = 'ingest_answer'\"\n        \" AND created_at > NOW() - make_interval(days => %s)\"\n        \" GROUP BY client_id, decision, blocked\",\n        (days,),\n    )\n    return portal_db.rows(cur)\n\n\ndef _recent(cur, days: int) -> List[Dict[str, Any]]:\n    import portal_ai_audit\n\n    cur.execute(\n        \"SELECT id, client_id, action, actor_kind, conversation_id, note,\"\n        \" created_at FROM \" + portal_db._q(portal_ai_audit.LOG_TABLE) +\n        \" WHERE created_at > NOW() - make_interval(days => %s)\"\n        \" AND (actor_kind = ANY(%s) OR action LIKE ANY(%s))\"\n        \" ORDER BY id DESC LIMIT %s\",\n        (days, list(portal_ai_audit.AI_ACTOR_KINDS),\n         portal_ai_audit._patterns(), max(1, RECENT_LIMIT)),\n    )\n    return portal_db.rows(cur)\n\n\ndef overview(cur, days: int = DEFAULT_DAYS) -> Dict[str, Any]:\n    \"\"\"Every workspace's AI posture + platform totals (read-only).\"\"\"\n    days = _days(days)\n    import portal_ai_usage\n    import portal_ai_audit\n\n    workspaces = _guarded(cur, \"workspaces\", lambda: _workspaces(cur)) or []\n    names = _by_client(_guarded(cur, \"names\", lambda: _names(cur)))\n    autonomy = _by_client(_guarded(cur, \"autonomy\", lambda: _autonomy(cur)))\n    agents = _by_client(_guarded(cur, \"agents\", lambda: _agents(cur)))\n    usage_rows = _guarded(cur, \"usage\", lambda: _usage(cur, days)) or []\n    escalations = _by_client(_guarded(cur, \"escalations\",\n                                      lambda: _escalations(cur)))\n    approvals = _by_client(_guarded(cur, \"approvals\", lambda: _approvals(cur)))\n    trace_rows = _guarded(cur, \"traces\", lambda: _traces(cur, days)) or []\n    recent_rows = _guarded(cur, \"recent\", lambda: _recent(cur, days)) or []\n\n    price_table = portal_ai_usage.prices()\n    usage: Dict[int, Dict[str, Any]] = {}\n    for row in usage_rows:\n        cid = int(row.get(\"client_id\") or 0)\n        entry = usage.setdefault(cid, {\"calls\": 0, \"failed\": 0, \"tokens\": 0,\n                                       \"cost_usd\": 0.0, \"priced\": False,\n                                       \"last_call_at\": None})\n        prompt = int(row.get(\"prompt_tokens\") or 0)\n        completion = int(row.get(\"completion_tokens\") or 0)\n        entry[\"calls\"] += int(row.get(\"calls\") or 0)\n        entry[\"failed\"] += int(row.get(\"failed\") or 0)\n        entry[\"tokens\"] += prompt + completion\n        cost = portal_ai_usage.estimate_cost(\n            str(row.get(\"model\") or \"\"), prompt, completion, price_table)\n        if cost is not None:\n            entry[\"cost_usd\"] = round(entry[\"cost_usd\"] + cost, 4)\n            entry[\"priced\"] = True\n        last = row.get(\"last_call_at\")\n        if last and (entry[\"last_call_at\"] is None\n                     or _iso(last) > str(entry[\"last_call_at\"])):\n            entry[\"last_call_at\"] = _iso(last)\n\n    traces: Dict[int, Dict[str, int]] = {}\n    for row in trace_rows:\n        cid = int(row.get(\"client_id\") or 0)\n        entry = traces.setdefault(cid, {\"answers\": 0, \"handoffs\": 0,\n                                        \"blocked\": 0})\n        if str(row.get(\"decision\") or \"\") == \"send\":\n            entry[\"answers\"] += int(row.get(\"n\") or 0)\n        else:\n            entry[\"handoffs\"] += int(row.get(\"n\") or 0)\n            if row.get(\"blocked\") is True:\n                entry[\"blocked\"] += int(row.get(\"n\") or 0)\n\n    # Universe: every workspace with users, plus any workspace that shows\n    # AI activity but no user row (never hide activity).\n    known = {int(w.get(\"client_id\") or 0) for w in workspaces}\n    extra = (set(usage) | set(autonomy) | set(agents)) - known - {0}\n    for cid in sorted(extra):\n        workspaces.append({\"client_id\": cid, \"email\": \"\", \"owner\": \"\",\n                           \"users\": 0})\n\n    items: List[Dict[str, Any]] = []\n    totals = {\"workspaces\": 0, \"auto\": 0, \"suggest\": 0, \"off\": 0,\n              \"agents_active\": 0, \"calls\": 0, \"failed\": 0, \"tokens\": 0,\n              \"cost_usd\": 0.0, \"priced\": bool(price_table),\n              \"open_escalations\": 0, \"pending_approvals\": 0,\n              \"answers\": 0, \"handoffs\": 0, \"blocked\": 0}\n    for ws in workspaces:\n        cid = int(ws.get(\"client_id\") or 0)\n        if cid <= 0:\n            continue\n        level = str((autonomy.get(cid) or {}).get(\"autonomy\") or \"suggest\")\n        if level not in AUTONOMY_LEVELS:\n            level = \"suggest\"\n        use = usage.get(cid) or {\"calls\": 0, \"failed\": 0, \"tokens\": 0,\n                                 \"cost_usd\": 0.0, \"priced\": False,\n                                 \"last_call_at\": None}\n        agent = agents.get(cid) or {}\n        trace = traces.get(cid) or {\"answers\": 0, \"handoffs\": 0,\n                                    \"blocked\": 0}\n        item = {\n            \"client_id\": cid,\n            \"name\": str((names.get(cid) or {}).get(\"business_name\") or \"\"),\n            \"owner\": str(ws.get(\"owner\") or \"\"),\n            \"email\": str(ws.get(\"email\") or \"\"),\n            \"users\": int(ws.get(\"users\") or 0),\n            \"autonomy\": level,\n            \"autonomy_updated_at\": _iso((autonomy.get(cid) or {}).get(\n                \"updated_at\")),\n            \"agents_active\": int(agent.get(\"active\") or 0),\n            \"agents_total\": int(agent.get(\"total\") or 0),\n            \"agents_draft_only\": int(agent.get(\"draft_only\") or 0),\n            \"calls\": int(use[\"calls\"]),\n            \"failed\": int(use[\"failed\"]),\n            \"tokens\": int(use[\"tokens\"]),\n            \"cost_usd\": (round(float(use[\"cost_usd\"]), 4)\n                         if use.get(\"priced\") else None),\n            \"last_call_at\": use.get(\"last_call_at\"),\n            \"open_escalations\": int((escalations.get(cid) or {}).get(\n                \"open\") or 0),\n            \"pending_approvals\": int((approvals.get(cid) or {}).get(\n                \"pending\") or 0),\n            \"answers\": int(trace[\"answers\"]),\n            \"handoffs\": int(trace[\"handoffs\"]),\n            \"blocked\": int(trace.get(\"blocked\") or 0),\n        }\n        items.append(item)\n        totals[\"workspaces\"] += 1\n        totals[level] += 1\n        totals[\"agents_active\"] += item[\"agents_active\"]\n        totals[\"calls\"] += item[\"calls\"]\n        totals[\"failed\"] += item[\"failed\"]\n        totals[\"tokens\"] += item[\"tokens\"]\n        if item[\"cost_usd\"] is not None:\n            totals[\"cost_usd\"] = round(totals[\"cost_usd\"] + item[\"cost_usd\"], 4)\n        totals[\"open_escalations\"] += item[\"open_escalations\"]\n        totals[\"pending_approvals\"] += item[\"pending_approvals\"]\n        totals[\"answers\"] += item[\"answers\"]\n        totals[\"handoffs\"] += item[\"handoffs\"]\n        totals[\"blocked\"] += item[\"blocked\"]\n    items.sort(key=lambda i: (-i[\"calls\"], i[\"client_id\"]))\n\n    recent = []\n    for row in recent_rows:\n        recent.append({\n            \"id\": int(row.get(\"id\") or 0),\n            \"client_id\": int(row.get(\"client_id\") or 0),\n            \"action\": str(row.get(\"action\") or \"\"),\n            \"category\": portal_ai_audit.categorize(\n                row.get(\"action\"), row.get(\"actor_kind\")),\n            \"actor_kind\": str(row.get(\"actor_kind\") or \"\"),\n            \"conversation_id\": (int(row[\"conversation_id\"])\n                                if row.get(\"conversation_id\") else None),\n            \"note\": str(row.get(\"note\") or \"\")[:300],\n            \"created_at\": _iso(row.get(\"created_at\")),\n        })\n\n    return {\n        \"days\": days,\n        \"generated_at\": datetime.now(timezone.utc).isoformat(),\n        \"controls\": platform_settings.ai_controls(),\n        \"totals\": totals,\n        \"workspaces\": items,\n        \"recent\": recent,\n    }\n\n\n@bp.get(\"/eval\")\ndef get_behavioral_eval():\n    \"\"\"Run the bounded, deterministic AI behavior contracts.\n\n    This intentionally makes zero provider calls and touches no tenant data;\n    it is a deploy-time smoke signal, not a customer-message evaluator.\n    \"\"\"\n    try:\n        import portal_ai_eval\n\n        return jsonify(portal_ai_eval.run_contract_suite()), 200\n    except Exception as error:\n        logger.warning(\"admin ai behavioral eval failed: %s\", error)\n        return jsonify({\"error\": {\n            \"code\": \"ai_eval_unavailable\",\n            \"message\": \"AI behavioral evaluation temporarily unavailable.\",\n        }}), 503\n\n\n\n\n@bp.get(\"/quality\")\ndef get_live_quality():\n    \"\"\"Platform-wide live quality sample over brain traces + usage.\n    Service-key only (before_request). Zero LLM cost. Optional\n    ?client_id= filters to one workspace; ?days=1|7|14|30.\"\"\"\n    try:\n        import portal_ai_quality\n        days = request.args.get(\"days\")\n        raw_client = request.args.get(\"client_id\")\n        client_id = None\n        if raw_client not in (None, \"\"):\n            try:\n                client_id = int(raw_client)\n                if client_id <= 0:\n                    client_id = None\n            except Exception:\n                client_id = None\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                data = portal_ai_quality.sample_quality(\n                    cur, client_id, days=days or portal_ai_quality.DEFAULT_DAYS\n                )\n            conn.commit()\n        finally:\n            conn.close()\n        return jsonify(data), 200\n    except Exception as error:\n        logger.warning(\"admin ai quality sample failed: %s\", error)\n        return jsonify({\"error\": {\n            \"code\": \"ai_quality_unavailable\",\n            \"message\": \"Live AI quality sampling temporarily unavailable.\",\n        }}), 503\n\n\n@bp.get(\"/overview\")\ndef get_overview():\n    days = _days(request.args.get(\"days\"))\n    try:\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                payload = overview(cur, days)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        logger.warning(\"admin ai overview failed: %s\", error)\n        return jsonify({\"error\": {\"code\": \"db_unavailable\",\n                                  \"message\": \"AI overview temporarily\"\n                                             \" unavailable.\"}}), 503\n    return jsonify(payload), 200\n\n\n# ---------------------------------------------------------------------------\n# per-workspace autonomy override\n# ---------------------------------------------------------------------------\n\ndef set_autonomy(cur, client_id: int, autonomy: str, reason: str = \"\") -> None:\n    \"\"\"Upsert one workspace's brain autonomy (platform admin override) and\n    audit it as actor ``platform_admin`` - inside the caller's transaction.\"\"\"\n    import portal_brain\n\n    portal_brain._ensure_ddl(cur)\n    cur.execute(\n        \"INSERT INTO \" + portal_db._q(portal_brain.SETTINGS_TABLE) +\n        \" (client_id, autonomy, updated_at) VALUES (%s, %s, NOW())\"\n        \" ON CONFLICT (client_id) DO UPDATE SET autonomy = EXCLUDED.autonomy,\"\n        \" updated_at = NOW()\",\n        (client_id, autonomy),\n    )\n    portal_db.log_action(\n        cur, client_id, \"brain.autonomy_override\", \"platform_admin\", None, None,\n        (\"Platform admin set AI autonomy to \" + autonomy\n         + ((\": \" + reason) if reason else \"\"))[:200],\n    )\n\n\n@bp.post(\"/clients/<int:client_id>/autonomy\")\ndef post_autonomy(client_id: int):\n    payload = request.get_json(silent=True) or {}\n    autonomy = str(payload.get(\"autonomy\") or \"\").strip().lower()\n    reason = str(payload.get(\"reason\") or \"\").strip()[:200]\n    if autonomy not in AUTONOMY_LEVELS:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"autonomy must be off, suggest\"\n                                             \" or auto.\"}}), 400\n    if client_id <= 0:\n        return jsonify({\"error\": {\"code\": \"bad_request\",\n                                  \"message\": \"client_id is required.\"}}), 400\n    try:\n        conn = portal_db._conn()\n        try:\n            with conn.cursor() as cur:\n                set_autonomy(cur, client_id, autonomy, reason)\n            conn.commit()\n        finally:\n            conn.close()\n    except Exception as error:\n        logger.warning(\"admin ai autonomy override failed: %s\", error)\n        return jsonify({\"error\": {\"code\": \"db_unavailable\",\n                                  \"message\": \"Could not update autonomy.\"}}), 503\n    try:\n        import portal_notify\n\n        portal_notify.notify(\n            client_id, \"system\", \"AI autonomy changed by the OmniFlow team\",\n            \"Your Business Brain now runs at autonomy '\" + autonomy + \"'.\"\n            + ((\" Reason: \" + reason) if reason else \"\")\n            + \" You can review this under Settings > AI Brain.\",\n            severity=\"high\" if autonomy == \"off\" else \"normal\",\n            dedupe_key=\"autonomy_override:\" + str(client_id) + \":\" + autonomy)\n    except Exception:\n        pass\n    return jsonify({\"ok\": True, \"client_id\": client_id,\n                    \"autonomy\": autonomy}), 200\n");
